function normalize(type,row,state={}){ let ref=refOf(row); if(CHILD_TYPES.has(type) && !(row.__ref||row.referenceId||row.reference||row.RefIDD||row.Reference_ID||row.ref||row.registryNumber)) ref=''; const st=statusOf(row,type); const rec={...row,__id:String(row.__id||row.id||row.ID||uid(type.toUpperCase())),__type:type,__ref:ref,__directorate:'',__phase:row.__phase||phaseOf(st),__status:st,__source:row.__source||'STATE',__sourceId:String(row.sourceId||row.ID||row.id||''),__createdAt:row.__createdAt||row.created||row.Created||new Date().toISOString(),__updatedAt:new Date().toISOString(),__version:row.__version||1}; rec.__directorate=deriveDirectorate(rec,state)||'UNSCOPED'; return rec; }
