export function writeArchive(ref,bundle){ if(!bundle?.ref||!bundle.records||!Array.isArray(bundle.auditThread)) throw createValidationError('Invalid archive bundle',{ref}); _archive.set(ref,deepFreeze(clone(bundle))); return getArchive(ref); }
export function markArchived(ref){ const b=_byRef.get(ref)||{}; Object.values(b).flat().forEach(r=>{r.__status='archived';r.__phase=6;}); }
export function getArchive(ref){ const a=_archive.get(ref); return a?freeze(a):null; }
export function quarantine(raw,reason){ const q={id:uid('Q'),at:new Date().toISOString(),reason,raw,reviewed:false}; _quarantine.set(q.id,q); AuditLog.record({ref:raw.__ref||raw.referenceId||'',event:'audit:quarantined',meta:{reason}}); return null; }
