export function snapshot(){ return freeze({store:Array.from(_store.entries()).map(([k,v])=>[k,Array.from(v.values())]),byRef:Array.from(_byRef.entries()),archive:Array.from(_archive.entries()),quarantine:Array.from(_quarantine.values())}); }
export function restoreSnapshot(s){ clear(); for(const [t,rows] of (s.store||[])) for(const r of rows) insert(r); for(const [r,b] of (s.archive||[])) _archive.set(r,b); }
export function stats(){ return freeze({types:Object.fromEntries(Array.from(_store.entries()).map(([k,v])=>[k,v.size])),references:_byRef.size,archives:_archive.size,quarantine:_quarantine.size}); }
function deepFreeze(v){ if(v&&typeof v==='object'){ Object.freeze(v); Object.values(v).forEach(deepFreeze); } return v; }

