import { createValidationError, createClosureError } from './errors.js';
export const LifecycleTransitions = Object.freeze({ arrival:['registered','duplicate','rejected','on_hold'], registered:['triaged','duplicate','rejected','on_hold','triage_complete'], triaged:['triage_complete'], triage_complete:['assigning','assigned'], assigning:['assigned','assignment_failed'], assignment_failed:['assigning','triage_complete'], assigned:['acknowledged','in_progress','reassign_requested'], acknowledged:['in_progress','blocked'], in_progress:['awaiting_response','action_complete','blocked'], blocked:['in_progress'], awaiting_response:['in_progress','action_complete'], action_complete:['pending_review'], pending_review:['approved','approved_with_edit','returned','escalated','rejected'], returned:['in_progress'], approved:['dispatch_pending'], approved_with_edit:['dispatch_pending'], escalated:['approved','returned','rejected'], dispatch_pending:['dispatch_in_flight','no_dispatch'], dispatch_in_flight:['dispatched','dispatch_failed'], dispatch_failed:['dispatch_pending','no_dispatch'], no_dispatch:['closure_check'], dispatched:['closure_check'], closure_check:['closed'], closed:['archived'], archived:['reopen_requested'], reopen_requested:['reopened_as_new_ref'] });
export function canTransition(fromStatus,toStatus){ return (LifecycleTransitions[fromStatus]||[]).includes(toStatus) || fromStatus===toStatus; }
export function assertTransitionAllowed(fromStatus,toStatus){ if(!canTransition(fromStatus,toStatus)) throw createValidationError(`Invalid lifecycle transition: ${fromStatus} -> ${toStatus}`,{fromStatus,toStatus}); return true; }
export function validateGate(toStatus,bundle,meta={},helpers={}){ if(toStatus==='action_complete' && !(meta.response||meta.summary||meta.taskId)) throw createValidationError('Action completion requires response evidence.',{toStatus}); if(toStatus==='returned' && !meta.reason) throw createValidationError('Return for revision requires a reason.',{toStatus}); if(toStatus==='approved_with_edit' && !meta.editDiff) throw createValidationError('Approve with edits requires an edit diff.',{toStatus}); if(toStatus==='no_dispatch' && !meta.reason) throw createValidationError('No-dispatch requires a reason.',{toStatus}); if(toStatus==='closed'){ const c=helpers.canClose?.(); if(c && !c.ok) throw createClosureError('Closure gate failed.',c); } return true; }

