const initial = { schemaVersion:AppConfig.stateSchemaVersion, profile:{name:'Registry',email:'dgsregistry@nitda.gov.ng',persona:'admin'}, settings:{theme:'light',density:'comfortable',maxBulkAssign:AppConfig.maxBulkAssign,endpoints:{...DefaultEndpointSettings},welcomeSeen:false,navCollapsed:null}, activities:[], tracking:[], correspondence:[], operations:[], registryFiles:[], fileMovements:[], registryMinutes:[], escalations:[], notifications:[], dispatches:[], correspondenceEmails:[], comments:[], approvals:[], users:bootstrapUsers, categories:[], departments:[], emails:[], audit:[], pending:[], runtime:{loading:false,lastLoad:null,lastError:null}, selectedId:null };
const clone = v => structuredClone(v);
function safeLocalStorage(){ try { return typeof localStorage !== 'undefined' ? localStorage : null; } catch { return null; } }
function hydrate(raw={}) { const p=raw.profile||{}, x=raw.settings||{}; const hydrated={...clone(initial),...raw,schemaVersion:AppConfig.stateSchemaVersion,profile:{...initial.profile,...p},settings:{...initial.settings,...x,endpoints:{...DefaultEndpointSettings,...(x.endpoints||{})},maxBulkAssign:Number.isInteger(+x.maxBulkAssign)&&+x.maxBulkAssign>0?+x.maxBulkAssign:AppConfig.maxBulkAssign}}; if(!Array.isArray(raw.users)||!raw.users.length) hydrated.users=clone(initial.users); return hydrated; }
let state; try { const ls=safeLocalStorage(); state=hydrate(JSON.parse(ls?.getItem(AppConfig.storageKey)||'{}')); } catch { state=clone(initial); }
const listeners=new Set();
function buildPatchAudit(p, meta={}){
  const keys=Object.keys(p||{}).filter(k=>k!=='audit'&&k!=='runtime');
