import { WelcomeExperienceConfig as C } from '../config/welcome-experience.config.js';
import { State } from './state.js';
const qs=()=>new URLSearchParams(location.search);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const uid=()=>crypto.randomUUID?.()||('wel_'+Date.now()+'_'+Math.random().toString(36).slice(2));
function safeStore(){ try{return localStorage}catch{return null} }
function shouldSkip(){ const q=qs(); if(!C.enabled) return true; if(C.skipQueryParams.some(k=>q.has(k))) return true; if(C.forceQueryParams.some(k=>q.has(k))) return false; return !!(State.get().settings?.welcomeSeen || safeStore()?.getItem(C.storageKey)); }
function markSeen(meta={}){ safeStore()?.setItem(C.storageKey,new Date().toISOString()); State.patch({settings:{...State.get().settings,welcomeSeen:true}, runtime:{...State.get().runtime,welcomeExperience:{...meta, seenAt:new Date().toISOString()}}},{module:'welcome-experience',action:'complete',event:'audit:welcome-completed'}); }
function greeting(){ const h=new Date().getHours(); return h<12?'Good Morning':h<17?'Good Afternoon':'Good Evening'; }
function liveDate(){ return new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}); }
function liveTime(){ return new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}); }
function maskEmail(email){ const [u,d]=String(email||'').split('@'); if(!d) return email||'your email'; return (u.slice(0,2)||'us')+'•'.repeat(Math.max((u.length||5)-2,3))+'@'+d; }
function maskPhone(p){ const s=String(p||'+2348012345678').replace(/\s+/g,''); return s.slice(0,4)+' ••• '+s.slice(-3); }
function deriveEmail(name){ return String(name||'registry').toLowerCase().replace(/[^a-z0-9]+/g,'.').replace(/^\.|\.$/g,'')+'@nitda.gov.ng'; }
function injectCss(){ if(document.getElementById('dgo-welcome-css')) return; const st=document.createElement('style'); st.id='dgo-welcome-css'; st.textContent=`
:root{--wel-green:#05583B;--wel-green-deep:#033E2A;--wel-smart:#17B255;--wel-ink:#373435;--wel-paper:#F6F8F6;--wel-muted:#66736C;--wel-line:#DDE7E1;--wel-danger:#C8102E;--wel-shadow:0 24px 60px rgba(5,88,59,.22);}
@keyframes welSpin{to{transform:rotate(360deg)}}@keyframes welRise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}@keyframes welPop{0%{transform:scale(.72);opacity:0}70%{transform:scale(1.05)}100%{transform:scale(1);opacity:1}}@keyframes welShake{10%,90%{transform:translateX(-2px)}20%,80%{transform:translateX(4px)}30%,50%,70%{transform:translateX(-6px)}40%,60%{transform:translateX(6px)}}
.dgo-wel{position:fixed;inset:0;z-index:2147483000;font-family:Outfit,Inter,Verdana,system-ui,sans-serif;background:var(--wel-green);color:#fff;overflow:hidden}.dgo-wel *{box-sizing:border-box}.dgo-wel [hidden]{display:none!important}.wel-layer{position:absolute;inset:0;transition:opacity .55s cubic-bezier(.2,0,0,1),transform .72s cubic-bezier(.2,0,0,1);}.wel-hidden{opacity:0;pointer-events:none;transform:scale(.98)}.wel-visible{opacity:1;pointer-events:auto;transform:scale(1)}.wel-brand-bg{background:radial-gradient(900px 560px at 50% 10%,rgba(23,178,85,.20),transparent 60%),linear-gradient(145deg,var(--wel-green),var(--wel-green-deep));}.wel-mark{width:42px;height:42px;border:3px solid var(--wel-smart);border-radius:50%;display:grid;place-items:center;position:relative}.wel-mark:before,.wel-mark:after{content:"";position:absolute;width:6px;height:6px;background:var(--wel-smart);border-radius:50%;top:16px}.wel-mark:before{left:-5px}.wel-mark:after{right:-5px}.wel-card{background:#fff;color:var(--wel-ink);border:1px solid var(--wel-line);border-radius:22px;box-shadow:var(--wel-shadow)}.wel-btn{border:0;border-radius:12px;height:44px;padding:0 16px;font-weight:800;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:8px}.wel-btn.primary{background:var(--wel-green);color:#fff}.wel-btn.primary:hover{background:var(--wel-smart);color:#022819}.wel-btn.secondary{background:#EEF4F0;color:var(--wel-green)}.wel-btn.ghost{background:transparent;color:var(--wel-muted)}.wel-btn:disabled{opacity:.55;cursor:not-allowed}.wel-input{width:100%;height:48px;border:1px solid var(--wel-line);background:#fff;border-radius:12px;padding:0 14px;font:600 14px inherit;color:var(--wel-ink)}.wel-input:focus{outline:none;border-color:var(--wel-smart);box-shadow:0 0 0 3px rgba(23,178,85,.18)}.wel-otp{height:54px;text-align:center;font-size:22px;font-weight:900;padding:0}.wel-meta{font-size:12px;color:var(--wel-muted)}.wel-overline{font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:900;color:var(--wel-smart)}.wel-shell{display:grid;grid-template-columns:44% 56%;height:100%}.wel-side{padding:48px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}.wel-side:after{content:"";position:absolute;right:-100px;bottom:-100px;width:360px;height:360px;border-radius:50%;border:1px solid rgba(255,255,255,.08)}.wel-side-title{font-size:24px;font-weight:900;line-height:1.25;max-width:360px}.wel-form{background:var(--wel-paper);display:flex;align-items:center;justify-content:center;padding:36px}.wel-form-inner{width:min(390px,100%);display:flex;flex-direction:column;gap:22px}.wel-tabs{display:inline-flex;background:#E9EFEA;border-radius:10px;padding:4px;align-self:flex-start}.wel-tab{border:0;background:transparent;border-radius:8px;height:34px;padding:0 14px;font-weight:800;cursor:pointer;color:var(--wel-muted)}.wel-tab.active{background:#fff;color:var(--wel-green)}.wel-step{display:flex;align-items:center;gap:9px;padding:4px 0;font-family:ui-monospace,Cascadia Mono,monospace;font-size:12px;color:rgba(255,255,255,.78)}.wel-check{color:var(--wel-smart);font-weight:900}.wel-progress-ring{width:170px;height:170px;border-radius:50%;display:grid;place-items:center;position:relative}.wel-progress-ring svg{position:absolute;inset:0;width:100%;height:100%;transform:rotate(-90deg)}.wel-progress-text{font-size:34px;font-weight:900}.wel-success-check{width:78px;height:78px;border-radius:50%;background:var(--wel-smart);display:grid;place-items:center;color:#fff;font-size:38px;animation:welPop .42s ease}.wel-toolbar{position:absolute;top:16px;right:16px;display:flex;gap:8px;z-index:5}.wel-toolbar button{height:34px;border-radius:9px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.10);color:#fff;font-weight:800;cursor:pointer;padding:0 10px}.wel-note{font-size:11px;color:#7B877F;line-height:1.45}.wel-error{color:var(--wel-danger);font-size:12px;font-weight:800}.wel-row{display:flex;align-items:center;justify-content:space-between;gap:12px}.wel-otp-row{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.wel-shake{animation:welShake .38s ease}.wel-hidden-a11y{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(1px,1px,1px,1px)}
@media(max-width:900px){.wel-shell{grid-template-columns:1fr}.wel-side{min-height:180px;padding:28px}.wel-side .wel-brand-message{display:none}.wel-form{align-items:flex-start;padding:28px 20px;overflow:auto}.wel-form-inner{max-width:520px}.wel-side-title{font-size:20px}}@media(max-width:520px){.wel-toolbar{left:12px;right:12px;justify-content:flex-end}.wel-progress-ring{width:142px;height:142px}.wel-progress-text{font-size:28px}.wel-otp-row{gap:6px}.wel-input.wel-otp{height:48px;font-size:19px}}
`; document.head.appendChild(st); }
function shell(){ const root=document.createElement('div'); root.className='dgo-wel'; root.setAttribute('role','dialog'); root.setAttribute('aria-modal','true'); root.setAttribute('aria-label','DGO Digital Ops welcome experience'); root.innerHTML=`<div class="wel-toolbar"><button data-skip>Skip</button><button data-restart hidden>Restart</button></div>
<section class="wel-layer wel-brand-bg wel-visible" data-phase="boot"><div style="position:absolute;top:22px;left:24px;display:flex;align-items:center;gap:12px"><div class="wel-mark"></div><div><div style="font-size:13px;font-weight:900">${esc(C.branding.agency)}</div><div style="font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.55)">${esc(C.branding.ministry)}</div></div></div><div style="height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:28px;padding:28px"><div class="wel-progress-ring"><svg viewBox="0 0 176 176"><circle cx="88" cy="88" r="78" fill="none" stroke="rgba(255,255,255,.16)" stroke-width="4"></circle><circle data-ring cx="88" cy="88" r="78" fill="none" stroke="var(--wel-smart)" stroke-width="4" stroke-linecap="round"></circle></svg><div><div class="wel-progress-text" data-progress>0%</div><div style="font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.55);text-align:center">Booting</div></div></div><div style="text-align:center"><div style="font-size:28px;font-weight:900">DG<span style="color:var(--wel-smart)">O</span> Digital Ops</div><div style="font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.55)">${esc(C.branding.subtitle)}</div><div style="margin:12px auto 0;height:3px;width:44px;background:var(--wel-smart);border-radius:999px"></div></div><div style="width:min(430px,90vw);min-height:110px" data-steps></div><div style="min-height:36px;font-size:13px;color:rgba(255,255,255,.62);text-align:center;max-width:600px" data-tip>${esc(C.tips[0])}</div></div><div style="position:absolute;bottom:22px;left:0;right:0;text-align:center;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.38);font-weight:800">${esc(C.branding.ministry)}</div></section>
<section class="wel-layer wel-hidden" data-phase="login">${loginHtml()}</section>
<section class="wel-layer wel-hidden" data-phase="otp">${otpHtml()}</section>
<section class="wel-layer wel-hidden" data-phase="verified"><div style="height:100%;display:flex;align-items:center;justify-content:center;background:var(--wel-paper);padding:28px"><div class="wel-card" style="width:min(480px,96vw);padding:36px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:16px"><div class="wel-success-check">✓</div><div style="font-size:25px;font-weight:900;color:var(--wel-ink)">Identity verified</div><div class="wel-meta" style="max-width:360px">Welcome, <b data-success-name>${esc(State.get().profile?.name||C.defaults.userName)}</b>. Your R11.6 session is secured and ready for Daily Operations.</div><button class="wel-btn primary" data-enter>Continue to Command Center</button><button class="wel-btn ghost" data-restart-inline>Restart welcome</button></div></div></section>`; return root; }
function loginHtml(){ const p=State.get().profile||{}; return `<div class="wel-shell"><aside class="wel-side wel-brand-bg"><div style="display:flex;align-items:center;gap:12px;position:relative"><div class="wel-mark"></div><div><div style="font-weight:900;font-size:18px">DG<span style="color:var(--wel-smart)">O</span> Digital Ops</div><div style="font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.55)">${esc(C.branding.subtitle)}</div></div></div><div class="wel-brand-message" style="position:relative"><div style="font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.55);font-weight:900;margin-bottom:12px">${esc(C.branding.agency)}</div><div class="wel-side-title">${esc(C.branding.tagline)}</div><div style="margin-top:18px;width:50px;height:3px;background:var(--wel-smart);border-radius:99px"></div></div><div style="position:relative;font-size:11px;color:rgba(255,255,255,.45)"><div style="font-weight:900;letter-spacing:.12em;text-transform:uppercase;margin-bottom:8px">${esc(C.branding.ministry)}</div><div class="wel-row"><span>${esc(C.branding.version)}</span><span data-live-date>${esc(liveDate())}</span></div></div></aside><main class="wel-form"><div class="wel-form-inner"><div><div class="wel-row" style="margin-bottom:14px"><span class="wel-overline" data-greeting>${esc(greeting())}</span><span class="wel-meta" data-live-time>${esc(liveTime())}</span></div><h1 style="margin:0;font-size:29px;letter-spacing:-.02em">${esc(p.name||C.defaults.userName)}</h1><div class="wel-meta" style="margin-top:6px">${esc(p.persona||C.defaults.userRole)} · Enter your email or phone to receive a one-time code.</div></div><div class="wel-tabs"><button class="wel-tab active" data-channel="email">Email</button><button class="wel-tab" data-channel="sms">Phone (SMS)</button></div><label><span class="wel-overline" data-identifier-label>Staff email or ID</span><input class="wel-input" data-identifier placeholder="registry@nitda.gov.ng" value="${esc(C.defaults.identifier||p.email||'')}"></label><label style="display:flex;align-items:center;gap:10px;color:var(--wel-muted);font-size:13px;font-weight:700"><input type="checkbox" data-remember checked> Remember this device</label><button class="wel-btn primary" data-send>Send Verification Code</button><div style="display:flex;align-items:center;gap:12px"><div style="height:1px;background:var(--wel-line);flex:1"></div><span class="wel-meta">or</span><div style="height:1px;background:var(--wel-line);flex:1"></div></div><button class="wel-btn secondary" data-sso>Continue with NITDA SSO (skip OTP)</button><div class="wel-note">Sessions are logged for auditability. Use is subject to Agency acceptable-use policies and DGO operational governance.</div></div></main></div>`; }
function otpHtml(){ return `<div class="wel-shell"><aside class="wel-side wel-brand-bg"><div style="display:flex;align-items:center;gap:12px"><div class="wel-mark"></div><div><div style="font-weight:900;font-size:18px">DG<span style="color:var(--wel-smart)">O</span> Digital Ops</div><div style="font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.55)">${esc(C.branding.subtitle)}</div></div></div><div class="wel-brand-message"><div style="font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.55);font-weight:900;margin-bottom:12px">${esc(C.branding.agency)}</div><div class="wel-side-title">Two-factor verification keeps every dispatch accountable.</div><div style="margin-top:18px;width:50px;height:3px;background:var(--wel-smart);border-radius:99px"></div></div><div style="font-size:11px;color:rgba(255,255,255,.45);font-weight:800;letter-spacing:.12em;text-transform:uppercase">${esc(C.branding.ministry)}</div></aside><main class="wel-form"><div class="wel-form-inner"><button class="wel-btn ghost" style="align-self:flex-start;padding:0" data-back>← Back</button><div><h1 style="margin:0;font-size:27px">Verify it is you</h1><div class="wel-meta" style="margin-top:6px">Enter the 6-digit code sent to <b data-masked>your destination</b>.</div></div><div class="wel-otp-row" data-otp-row>${Array.from({length:6},(_,i)=>`<input class="wel-input wel-otp" inputmode="numeric" maxlength="1" aria-label="OTP digit ${i+1}" data-otp="${i}">`).join('')}</div><div class="wel-error" data-otp-error hidden>Incorrect code. Please try again.</div><button class="wel-btn primary" data-verify disabled>Verify & Continue</button><div style="text-align:center" class="wel-meta"><span data-resend-label>Resend code in ${C.resendSeconds}s</span> <button class="wel-btn ghost" style="height:auto;padding:0;color:var(--wel-green)" data-resend hidden>Resend code</button></div><button class="wel-btn ghost" style="height:auto" data-switch-channel>Send code via SMS instead</button><div class="wel-note">Demo mode accepts any 6-digit code except 000000. Production OTP endpoints remain available through the R11.6 endpoint contract configuration.</div></div></main></div>`; }

const WELCOME_FOCUSABLE='a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function welcomeFocusables(root){ return Array.from(root.querySelectorAll(WELCOME_FOCUSABLE)).filter(x=>!x.hidden && x.offsetParent!==null); }
function focusWelcomePhase(root){ const active=root.querySelector('.wel-visible')||root; const preferred=active.querySelector('[data-identifier],.wel-otp,[data-enter],[data-send],button:not([disabled]),input:not([disabled]),select:not([disabled])'); const target=(preferred&&preferred.offsetParent!==null?preferred:null)||welcomeFocusables(active)[0]||welcomeFocusables(root)[0]||root; try{ target.focus({preventScroll:true}); }catch{ try{ target.focus(); }catch{} } }
