function setChannel(ch){ model.channel=ch; $$('[data-channel]').forEach(b=>b.classList.toggle('active',b.dataset.channel===ch)); const lab=$('[data-identifier-label]'), inp=$('[data-identifier]'); if(ch==='sms'){ lab.textContent='Phone number'; inp.placeholder='+234 801 234 5678'; } else { lab.textContent='Staff email or ID'; inp.placeholder='registry@nitda.gov.ng'; } const sw=$('[data-switch-channel]'); if(sw) sw.textContent=ch==='email'?'Send code via SMS instead':'Send code via email instead'; }
$$('[data-channel]').forEach(b=>b.onclick=()=>setChannel(b.dataset.channel)); $('[data-identifier]').oninput=e=>{ model.identifier=e.target.value.trim(); }; $('[data-remember]').onchange=e=>{ model.remember=e.target.checked; }; $('[data-send]').onclick=async()=>{ const id=$('[data-identifier]').value.trim(); if(!id) { $('[data-identifier]').focus(); return; } model.identifier=id; const btn=$('[data-send]'); btn.disabled=true; btn.textContent='Sending code...'; await sleep(750); btn.disabled=false; btn.textContent='Send Verification Code'; setPhase('otp'); prepareOtp(); }; $('[data-sso]').onclick=async()=>{ const btn=$('[data-sso]'); btn.disabled=true; btn.textContent='Securing session...'; await sleep(650); setPhase('verified'); cleanup(); }; function prepareOtp(){ $('[data-masked]').textContent=maskDestination(); model.otp=['','','','','','']; $$('.wel-otp').forEach((i,idx)=>{ i.value=''; i.oninput=e=>{ const v=e.target.value.replace(/[^0-9]/g,'').slice(-1); e.target.value=v; model.otp[idx]=v; $('[data-otp-error]').hidden=true; $('[data-otp-row]').classList.remove('wel-shake'); if(v && $$('.wel-otp')[idx+1]) $$('.wel-otp')[idx+1].focus(); updateVerify(); }; i.onkeydown=e=>{ if(e.key==='Backspace'&&!i.value&&$$('.wel-otp')[idx-1]) $$('.wel-otp')[idx-1].focus(); }; i.onpaste=e=>{ e.preventDefault(); const digs=(e.clipboardData.getData('text')||'').replace(/[^0-9]/g,'').slice(0,6).split(''); digs.forEach((d,j)=>{ model.otp[j]=d; $$('.wel-otp')[j].value=d; }); updateVerify(); ($$('.wel-otp')[Math.min(digs.length,5)]||$$('.wel-otp')[0]).focus(); }; }); $$('.wel-otp')[0]?.focus(); startResend(); }
function updateVerify(){ $('[data-verify]').disabled=!model.otp.every(Boolean); } $('[data-back]').onclick=()=>{ clearInterval(model.timer); setPhase('login'); }; $('[data-switch-channel]').onclick=()=>{ setChannel(model.channel==='email'?'sms':'email'); $('[data-masked]').textContent=maskDestination(); startResend(); }; $('[data-resend]').onclick=()=>{ if(model.resend>0) return; startResend(); $('[data-masked]').textContent=maskDestination(); }; $('[data-verify]').onclick=async()=>{ const code=model.otp.join(''); const btn=$('[data-verify]'); btn.disabled=true; btn.textContent='Verifying...'; await sleep(700); if(code===C.invalidDemoOtp){ btn.textContent='Verify & Continue'; btn.disabled=false; model.otp=['','','','','','']; $$('.wel-otp').forEach(i=>i.value=''); $('[data-otp-error]').hidden=false; $('[data-otp-row]').classList.add('wel-shake'); updateVerify(); $$('.wel-otp')[0]?.focus(); return; } btn.textContent='Verify & Continue'; setPhase('verified'); cleanup(); }; function startResend(){ clearInterval(model.timer); model.resend=C.resendSeconds; const lab=$('[data-resend-label]'), btn=$('[data-resend]'); if(btn) btn.hidden=true; if(lab) lab.textContent=`Resend code in ${model.resend}s`; model.timer=setInterval(()=>{ model.resend-=1; if(model.resend<=0){ clearInterval(model.timer); if(lab) lab.textContent="Didn't get a code?"; if(btn) btn.hidden=false; } else if(lab) lab.textContent=`Resend code in ${model.resend}s`; },1000); }
async function bootAnim(){ const ring=$('[data-ring]'), prog=$('[data-progress]'), steps=$('[data-steps]'), tip=$('[data-tip]'); const r=78, c=2*Math.PI*r; ring.setAttribute('stroke-dasharray',String(c)); let start=performance.now(), lastStep=-1, tipIdx=0; while(model.phase==='boot'){ const elapsed=performance.now()-start, pct=Math.min(100,Math.round(elapsed/C.bootDurationMs*100)); ring.setAttribute('stroke-dashoffset',String(c*(1-pct/100))); prog.textContent=pct+'%'; const step=Math.min(C.bootSteps.length-1,Math.floor(pct/100*C.bootSteps.length)); if(step!==lastStep){ lastStep=step; const done=C.bootSteps.slice(Math.max(0,step-3),step).map(s=>`<div class="wel-step"><span class="wel-check">✓</span><span>${esc(s)}</span></div>`).join(''); steps.innerHTML=done+`<div class="wel-step"><span style="animation:welSpin .9s linear infinite;display:inline-block">◌</span><b>${esc(C.bootSteps[step]||C.bootSteps.at(-1))}</b></div>`; }
 if(Math.floor(elapsed/2600)!==tipIdx){ tipIdx=Math.floor(elapsed/2600); tip.textContent=C.tips[tipIdx%C.tips.length]; }
 if(pct>=100) break; await sleep(80); } if(model.phase==='boot'){ await sleep(450); setPhase('login'); } }
setChannel(model.channel); bootAnim(); }); }

core/write-manager.js.content:
import { State } from './state.js';
import { DataClient } from './data-client.js';
import { PendingQueue } from './pending-queue.js';
import { Idempotency } from './idempotency.js';
import { auditAction } from './action-authority.js';
import { toast } from './ui.js';
const clone=v=>structuredClone(v);
export const WriteManager=Object.freeze({local,backend,optimistic,commit:(args)=>backend(args)});
export async function local({module,action,patch,ref='',message=''}){ State.patch(patch,{module,action,ref}); auditAction(module,action,{ref,meta:{local:true}}); if(message) toast?.(message,'success'); return {ok:true,source:'local',patch}; }
export async function backend({module,action,endpoint='DYNAMIC_ACTIONS',payload={},ref='',message=''}){ const actor=State.get().profile||{}; const idempotencyKey=await Idempotency.key({operation:action,ref,actor,payload}); const res=await DataClient.request(endpoint,{operation:action,ref,idempotencyKey,...payload}); auditAction(module,action,{ref,meta:{backend:endpoint,idempotencyKey}}); if(message) toast?.(message,'success'); return res; }
export async function optimistic({module,action,patch,endpoint='DYNAMIC_ACTIONS',payload={},ref='',rollbackOnFailure=true,message=''}){ const before=clone(State.get()); State.patch(patch,{module,action,ref}); try{return await backend({module,action,endpoint,payload,ref,message});}catch(e){ if(rollbackOnFailure) State.patch(before,{module:'write-manager',action:'rollback',ref,silent:true}); else PendingQueue.enqueue({key:endpoint,payload,ref,error:e.message,operation:action}); throw e;} }

