import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import{State}from'../core/state.js';import {head,kpis,esc,badge,toast,confirmAction,mdBack,mdSwitch,resetDetailScroll,fmtDate} from '../core/ui.js';import{UIState,pageSlice,pager}from'../core/ui-state.js';import{OperationStates,enrichOperation,audit}from'../core/enterprise-domain.js';import{invoke}from'../core/api.js';import{memoizeBySignature,capRows,RenderBudget}from'../core/render-budget.js';import{priorityOptions,priorityLabel,priorityTone}from'../config/priority.config.js';import{debouncedInput}from'../core/ui-interactions.js';import { filterItemsBySource, sourceFilterChips, sourceBadge } from '../core/source-views.js';
const memoOps=memoizeBySignature(rows=>rows.map(x=>enrichOperation(x)));
export async function mount(el){hydrateGovernance();render(el)}
function render(el){const s=State.get(),u=UIState.get('operations',{q:'',status:'All',scope:'All',page:1,size:25,selected:null,md:'list',editing:false,source:'all'}),ops=s.operations?.length?s.operations:memoOps(s.tracking),sourceRows=filterItemsBySource(ops,u.source||'all'),me=s.profile.email,now=Date.now(),rows=sourceRows.filter(o=>(u["status"] ==='All'||o["status"] ===u.status)&&(u.scope==='All'||u.scope==='My Work'&&o.owner.toLowerCase()===me.toLowerCase()||u.scope==='Overdue'&&o.dueDate&&new Date(o.dueDate)<now&&o.status!=='Completed'||u.scope==='Escalated'&&o.escalationLevel>0)&&(!u.q||[o.title,o.referenceId,o.owner,o.dsu,o.status].some(v=>String(v||'').toLowerCase().includes(u.q.toLowerCase())))),p=pageSlice(rows,u.page,u.size),sel=ops.find(x=>x.id===u.selected),over=ops.filter(o=>o.dueDate&&new Date(o.dueDate)<now&&!['Completed','Closed'].includes(o.status));el.innerHTML=`<div class="workspace">${head('Activities','A cross-domain work lens over correspondence, tasks and registry — review lifecycle, SLA and escalation, then open the owning workspace to act.')}${kpis([['Open',sourceRows.filter(x=>!['Completed','Closed'].includes(x.status)).length],['My work',sourceRows.filter(x=>x.owner.toLowerCase()===me.toLowerCase()).length],['Overdue',over.length],['Escalated',sourceRows.filter(x=>x.escalationLevel>0).length]])}${sourceFilterChips(u.source||'all','data-source-view',ops)}<div class="toolbar"><input data-q value="${esc(u.q)}" placeholder="Search work, reference or owner"><select data-scope>${['All','My Work','Overdue','Escalated'].map(x=>`<option>${x}</option>`).join('')}</select><select data-status><option>All</option>${OperationStates.map(x=>`<option>${x}</option>`).join('')}</select><a class="btn" href="#/single-assignment">Open Assignment Desk</a><a class="btn ghost" href="#/bulk-assignment">Open Bulk Assignment</a></div><div class="split" ${mdSwitch(sel?u.md:'list')}><div><div class="list-col">${p.rows.map(o=>`<article class="list-item ${o.id===u.selected?'active':''}" data-select="${esc(o.id)}"><div class="status-strip">${sourceBadge(o)} ${badge(o.status,o["status"] ==='Escalated'?'danger':'')} ${badge(priorityLabel(o.priority),priorityTone(o.priority))}</div><h4>${esc(o.title)}</h4><div class="meta">${esc(o.referenceId||'No reference')} · ${esc(o.owner||'Unassigned')} · ${esc(o.dueDate?fmtDate(o.dueDate):'No due date')}</div><div class="progress"><i style="width:${o.progress}%"></i></div></article>`).join('')||'<div class="empty">No work matches this queue.</div>'}</div>${pager(p)}</div><div class="detail-col panel-stack">${sel?detail(sel,s,u):'<section class="panel"><div class="empty"><h2>Select work</h2><p>Manage the complete operational lifecycle and linked records.</p></div></section>'}</div></div></div>`;bind(el,s,u,ops,sel)}
function detail(o,s,u){const corr=s.correspondence.find(x=>x.referenceId&&x.referenceId===o.referenceId),file=s.registryFiles.find(x=>x.referenceId&&x.referenceId===o.referenceId),comments=s.comments.filter(x=>x.referenceId===o.referenceId),approvals=s.approvals.filter(x=>x.ref===o.referenceId);return`${mdBack('Back to work queue')}<section class="panel"><div class="eyebrow panel-eyebrow">Work Record</div><div class="status-strip">${badge(o.status)} ${o.escalationLevel?badge('Escalation L'+o.escalationLevel,'danger'):''}</div><h2>${esc(o.title)}</h2><dl class="detail-grid"><dt>Reference</dt><dd>${esc(o.referenceId||'—')}</dd><dt>Owner</dt><dd>${esc(o.owner||'Unassigned')}</dd><dt>DSU</dt><dd>${esc(o.dsu||'—')}</dd><dt>Due</dt><dd>${esc(o.dueDate||'Not set')}</dd><dt>Progress</dt><dd>${o.progress}%</dd><dt>Registry</dt><dd>${esc(file?.registryNumber||'Not registered')}</dd></dl><p>${esc(o.description||'No instruction recorded.')}</p><div class="chips"><span class="chip">${corr?'Correspondence linked':'No correspondence link'}</span><span class="chip">${comments.length} comments</span><span class="chip">${approvals.length} approvals</span><span class="chip">${o.dependencies.length} dependencies</span></div><div class="form-row"><button type="button" class="btn ${u.editing?'ghost':''}" data-edit-toggle>${u.editing?'Close editor':'Update work state'}</button><button type="button" class="btn ghost" data-comments>Comments</button><button type="button" class="btn ghost" data-approval>Request approval</button><button type="button" class="btn ghost" data-registry>Open in Registry</button></div></section>${u.editing?`<section class="panel"><div class="eyebrow panel-eyebrow">Update Work State</div><form class="grid" data-update><label>Status<select name="status">${OperationStates.map(x=>`<option ${x===o.status?'selected':''}>${x}</option>`).join('')}</select></label><label>Progress<input name="progress" type="number" min="0" max="100" value="${o.progress}"></label><label>Owner<input name="owner" type="email" list="ops-users" value="${esc(o.owner)}"><datalist id="ops-users">${capRows(s.users,RenderBudget.tableRows).map(x=>`<option value="${esc(x.email)}">${esc(x.fullName)}</option>`).join('')}</datalist></label><label>Due date<input name="dueDate" type="date" value="${esc(fmtDate(o.dueDate||''))}"></label><label>Priority<select name="priority">${priorityOptions(o.priority)}</select></label><label>Escalation level<select name="escalationLevel">${[0,1,2,3].map(x=>`<option ${x===o.escalationLevel?'selected':''}>${x}</option>`).join('')}</select></label><label class="wide">Blocked reason<input name="blockedReason" value="${esc(o.blockedReason)}"></label><label class="wide">Dependencies (comma-separated refs)<input name="dependencies" value="${esc(o.dependencies.join(', '))}"></label><div class="wide form-row"><button class="btn">Save work state</button><button type="button" class="btn ghost" data-edit-cancel>Cancel</button></div></form></section>`:''}<section class="panel"><div class="eyebrow panel-eyebrow">Work Journal</div><ul class="timeline">${capRows(s.audit.filter(a=>a.entityId===o.id||a.details?.referenceId===o.referenceId),RenderBudget.timelineItems).map(a=>`<li><div class="when">${esc(a.at)}</div><b>${esc(a.action)}</b><p>${esc(a.actor||'System')}</p></li>`).join('')||'<li>No journal entries.</li>'}</ul></section>`}
function bind(el,s,u,ops,sel){el.querySelectorAll('[data-source-view]').forEach(b=>b.onclick=()=>{UIState.set('operations',{source:b.dataset.sourceView,page:1});render(el)});el.querySelector('[data-scope]').value=u.scope;el.querySelector('[data-status]').value=u.status;el.querySelector('[data-scope]').onchange=e=>{UIState.set('operations',{scope:e.target.value,page:1});render(el)};el.querySelector('[data-status]').onchange=e=>{UIState.set('operations',{status:e.target.value,page:1});render(el)};debouncedInput(el.querySelector('[data-q]'),v=>{UIState.set('operations',{q:v,page:1});render(el)},{refind:()=>el.querySelector('[data-q]')});el.querySelectorAll('[data-select]').forEach(x=>x.onclick=()=>{UIState.set('operations',{selected:x.dataset.select,md:'detail'});render(el);resetDetailScroll(el)});el.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{UIState.set('operations',{page:+x.dataset.page});render(el)});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('operations',{md:'list'});render(el)});el.querySelector('[data-edit-toggle]')?.addEventListener('click',()=>{UIState.set('operations',{editing:!u.editing});render(el)});el.querySelector('[data-edit-cancel]')?.addEventListener('click',()=>{UIState.set('operations',{editing:false});render(el)});el.querySelector('[data-comments]')?.addEventListener('click',()=>{State.patch({selectedId:sel.id});location.hash='#/comments'});el.querySelector('[data-approval]')?.addEventListener('click',()=>{State.patch({selectedId:sel.id});location.hash='#/approvals'});el.querySelector('[data-registry]')?.addEventListener('click',()=>{State.patch({selectedId:sel.referenceId||sel.id});location.hash='#/registry'});el.querySelector('[data-update]')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),progress=Math.max(0,Math.min(100,+d.progress||0)),level=+d.escalationLevel||0;if(d["status"] ==='Completed'&&progress<100)return toast('Completed work must be 100% progressed','error');if(d["status"] ==='Blocked'&&!d.blockedReason.trim())return toast('A blocked reason is required','error');if(!await confirmAction({title:'Update operational state',body:`<p>${esc(sel.title)}</p><p>${esc(sel.status)} → ${esc(d.status)}</p>`}))return;await executeOwnedAction('activities','update-operation',()=>{const updated={...sel,...d,progress,escalationLevel:level,dependencies:d.dependencies.split(',').map(x=>x.trim()).filter(Boolean),updatedAt:new Date().toISOString()};const event=audit('Operation Updated','operation',sel.id,{referenceId:sel.referenceId,from:sel.status,to:d.status,progress},s.profile.email);State.patch({operations:ops.map(x=>x.id===sel.id?updated:x),tracking:s.tracking.map(x=>String(x.id)===sel.id?{...x,status:d.status,progress:String(progress),assignedTo:d.owner,due:d.dueDate,priority:d.priority}:x),escalations:level?[{id:crypto.randomUUID(),operationId:sel.id,referenceId:sel.referenceId,level,reason:d.blockedReason,status:'Open',createdAt:new Date().toISOString()},...s.escalations]:s.escalations,audit:[event,...s.audit]});invoke('DYNAMIC_ACTIONS',{action:'transition',ref:sel.referenceId||sel.id,status:d.status,progress,owner:d.owner}).catch(()=>toast('Saved locally; synchronization queued','error'));},{ref:sel.referenceId||sel.id});toast('Work state saved','success');UIState.set('operations',{editing:false});render(el)})}

