import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';import { AppConfig } from '../config/app.config.js';import { head,toast,confirmAction,esc } from '../core/ui.js';import { invoke } from '../core/api.js';
import { UIState } from '../core/ui-state.js';import { ActionRuntime } from '../core/action-runtime.js';import { priorityOptions } from '../config/priority.config.js';
import { buildBulkAssignmentPayload, validateBulkAssignmentPayload, assignmentPreviewHtml } from '../core/assignment-payload.js';
import { AssignmentCascade } from '../core/assignment-cascade.js';
export const OTP_THRESHOLD = 25;
export async function mount(el){hydrateGovernance();AssignmentCascade.seedFallbackIfEmpty();render(el)}
const splitIds=v=>[...new Set(String(v||'').split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean))];
function render(el){const s=State.get();const raw=Number(s.settings?.maxBulkAssign);const cap=Number.isInteger(raw)&&raw>0?raw:AppConfig.maxBulkAssign;const u=UIState.get('bulk-assignment',{otp:null,draft:null});let draft=AssignmentCascade.cascade({draft:u.draft||{},state:s});const cats=AssignmentCascade.categories(s), subs=AssignmentCascade.subcategories(draft.category,s), deps=AssignmentCascade.departments(s);el.innerHTML=`<div class="workspace">${head('Bulk Assignment','Controlled bulk action with cascading category/DSU logic, existing cap, preview, OTP gate and endpoint payload parity.')}<form class="panel grid"><label class="wide">Activity IDs<textarea name="ids" rows="4" required placeholder="Paste IDs separated by comma, space or new line">${esc(u.draft?.ids||'')}</textarea></label><label>Category<select name="category" required><option value="">Select category</option>${cats.map(x=>`<option value="${esc(x.category)}" ${x.category===draft.category?'selected':''}>${esc(x.category)}</option>`).join('')}</select></label><label>Subcategory<select name="subcategory"><option value="">Select subcategory</option>${subs.map(x=>`<option value="${esc(x.subcategory)}" ${x.subcategory===draft.subcategory?'selected':''}>${esc(x.subcategory)}</option>`).join('')}</select></label><label>Category code<input name="categoryCode" value="${esc(draft.categoryCode||'')}"></label><label>Subcategory code<input name="subcategoryCode" value="${esc(draft.subcategoryCode||'')}"></label><label>Primary DSU<select name="dsu"><option value="">Select DSU</option>${deps.map(d=>`<option value="${esc(d.dsuKey)}" ${d.dsuKey===draft.dsu?'selected':''}>${esc(d.title||d.dsuKey)}</option>`).join('')}</select></label><label>Support DSU<select name="supportDsu"><option value="">Select support DSU</option>${deps.map(d=>`<option value="${esc(d.dsuKey)}" ${d.dsuKey===draft.supportDsu?'selected':''}>${esc(d.title||d.dsuKey)}</option>`).join('')}</select></label><label>Assigned To<input name="assignedTo" type="email" value="${esc(draft.assignedTo||'')}"></label><label>Supporting Assignee<input name="supportingAssignee" type="email" value="${esc(draft.supportingAssignee||'')}"></label><label class="wide">CC recipients<input name="copy" type="text" value="${esc(draft.copy||'')}"></label><label>Start date<input name="startDate" type="date" value="${esc(draft.startDate||'')}"></label><label>Ack due<input name="ack" type="date" value="${esc(draft.ack||'')}"></label><label>Due date<input name="due" type="date" value="${esc(draft.due||'')}"></label><label>Priority<select name="priority">${priorityOptions(draft.priority||'normal')}</select></label><label>MAX_BULK_ASSIGN<input value="${esc(cap)}" readonly></label><label class="wide">Instruction<textarea name="comments" rows="3" placeholder="Shared instruction for all selected records">${esc(draft.comments||'')}</textarea></label>${u.otp?`<label class="wide">OTP verification code (batch of ${u.otp.count} exceeds ${OTP_THRESHOLD})<input name="otp" inputmode="numeric" autocomplete="one-time-code" placeholder="Enter the 6-digit code" required></label>`:''}<div class="wide form-row"><button class="btn">${u.otp?'Verify OTP & Preview':'Preview & Apply'}</button>${u.otp?'<button type="button" class="btn ghost" data-otp-cancel>Cancel OTP step</button>':''}</div></form></div>`;
  const form=el.querySelector('form'); const collect=()=>Object.fromEntries(new FormData(form)); const updateDraft=(changed='manual')=>{ const d={...collect(),ids:form.ids.value}; const next=AssignmentCascade.cascade({draft:d,state:State.get(),changed}); UIState.set('bulk-assignment',{...UIState.get('bulk-assignment'),draft:{...d,...next}}); render(el); };
  ['category','subcategory','dsu','supportDsu','priority'].forEach(n=>form.elements[n]?.addEventListener('change',()=>updateDraft(n))); form.querySelectorAll('input,textarea,select').forEach(x=>x.addEventListener('input',()=>UIState.set('bulk-assignment',{...UIState.get('bulk-assignment'),draft:{...collect(),ids:form.ids.value}}))); el.querySelector('[data-otp-cancel]')?.addEventListener('click',()=>{UIState.set('bulk-assignment',{...UIState.get('bulk-assignment'),otp:null});render(el)});
  form.onsubmit=async e=>{e.preventDefault();const d=collect();const ids=splitIds(d.ids);if(!ids.length)return toast('Enter at least one activity ID','error');if(ids.length>cap)return toast('Bulk limit exceeded','error');const current=State.get(),known=new Set(current.activities.map(a=>String(a.id))),missing=ids.filter(id=>!known.has(id));if(missing.length)return toast('Unknown activity IDs: '+missing.join(', '),'error');const cascade=AssignmentCascade.cascade({draft:d,state:current,changed:'submit'});const merged={...d,...cascade,ids:d.ids,cascadeSnapshot:cascade.cascadeSnapshot};const draftErrors=AssignmentCascade.validateDraft(merged);if(draftErrors.length)return toast(draftErrors.join('; '),'error');if(ids.length>OTP_THRESHOLD&&!u.otp){let challenge;try{const res=await ActionRuntime.run('bulk-assignment','request-otp',{purpose:'bulk-assignment',refs:ids.slice(0,5),operation:'BULK_ASSIGNMENT'});challenge={requestId:res?.requestId||crypto.randomUUID(),code:null,backend:true,count:ids.length};toast('OTP requested — check your registered channel','success')}catch{const code=String(Math.floor(100000+Math.random()*900000));challenge={requestId:crypto.randomUUID(),code,backend:false,count:ids.length};toast('OTP endpoint unavailable — offline code: '+code,'info')}UIState.set('bulk-assignment',{...u,otp:challenge,draft:{...merged,ids:d.ids}});return render(el)} if(u.otp){const entered=String(d.otp||'').trim();if(u.otp.backend){try{await ActionRuntime.run('bulk-assignment','verify-otp',{requestId:u.otp.requestId,otp:entered,operation:'BULK_ASSIGNMENT',refs:ids.slice(0,5)})}catch{return toast('OTP verification failed','error')}}else if(entered!==u.otp.code){return toast('OTP verification failed','error')}} const payload=buildBulkAssignmentPayload({ids,form:merged,actor:current.profile,otpVerified:ids.length>OTP_THRESHOLD});const errors=validateBulkAssignmentPayload(payload);if(errors.length)return toast(errors.join('; '),'error');if(!await confirmAction({title:'Preview & confirm bulk assignment',body:`<p>Apply governed bulk assignment to ${ids.length} record(s).${ids.length>OTP_THRESHOLD?' <b>OTP verified.</b>':''}</p>${assignmentPreviewHtml(payload)}`,confirmText:'Apply bulk assignment',cancelText:'Cancel'}))return;await executeOwnedAction('bulk-assignment','bulk-assign',()=>{const activities=current.activities.map(a=>ids.includes(String(a.id))?{...a,category:payload.category,subcategory:payload.subcategory,categoryCode:payload.categoryCode,subcategoryCode:payload.subcategoryCode,assignmentStatus:'Assigned',assignedTo:payload.assignedTo,assignedDsu:payload.assignedToDsu,supportingAssignee:payload.supportingAssignee,supportingDsu:payload.supportingDsu,ccRecipients:payload.ccRecipients,priority:payload.priority,due:payload.due,ack:payload.ack,cascadeSnapshot:payload.cascadeSnapshot}:a);State.patch({activities},{module:'bulk-assignment',action:'assignment:bulk-cascaded',ref:ids.length+' record(s)'});invoke('BULK_ASSIGNMENT',payload).catch(()=>toast('Saved locally; sync queued','error'));},{ref:ids.length+' record(s)',meta:{count:ids.length,otp:ids.length>OTP_THRESHOLD,preview:true,cascade:payload.cascadeSnapshot?.rule?.id}});UIState.set('bulk-assignment',{otp:null,draft:null});toast(ids.length+' records updated','success');render(el)};
}

