import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { head, kpis, esc, badge, toast, confirmAction, mdBack, mdSwitch, resetDetailScroll, resetWorkspaceScroll,fmtDateTime, actionPreview} from '../core/ui.js';
import { UIState, pageSlice, pager } from '../core/ui-state.js';
import { CorrespondenceStates, enrichCorrespondence, audit } from '../core/enterprise-domain.js';
import { invoke } from '../core/api.js';
import { duplicateSummary, RenderBudget, capRows } from '../core/render-budget.js';
import { setCorrespondenceStatus } from '../core/enterprise-domain.js';
import { priorityOptions, priorityLabel, priorityTone, isElevatedPriority, normalizePriority } from '../config/priority.config.js';
import { debouncedInput } from '../core/ui-interactions.js';
import { exportCsv } from '../core/report-export-service.js';
import { requestSync } from '../core/data-loader.js';
import { relatedTasks, relatedEmails } from '../core/data-selectors.js';
import { inferSourceId, filterItemsBySource, sourceFilterChips, sourceBadge } from '../core/source-views.js';
import { mountAssignmentForm } from './single-assignment.js';
export function openCreate(){ UIState.set('correspondence',{creating:true,selected:null,tab:'intake'}); }
const statusList=['Pending','Accepted','Declined','Delegated','Archived'];
const categoryList=['Ministerial Directive','Event Invitation','Meeting Request','Project Proposal','Official Correspondence'];
const baseRows=s=>s.correspondence?.length?s.correspondence:s.activities.map(a=>enrichCorrespondence(a));
function cleanBody(t){return String(t||'').replace(/&nbsp;/gi,' ').replace(/&copy;/gi,'©').replace(/&amp;/gi,'&').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>').replace(/&quot;/gi,'"').replace(/&#0?39;|&apos;/gi,"'").replace(/<br\s*\/?>(?=)/gi,'\n').replace(/<\/(p|div|li|tr|h[1-6])>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/[ \t ]+/g,' ').replace(/\s*\n\s*/g,'\n').replace(/\n{3,}/g,'\n\n').trim();}
const bodyBlock=t=>{const c=cleanBody(t);return c?`<div class="record-body">${esc(c)}</div>`:'<p class="meta">No remarks recorded.</p>';};
const matches=(r,q)=>!q||[r.subject,r.referenceId,r.sender,r.senderEmail,r.category,r.assignedTo,r.id].some(v=>String(v||'').toLowerCase().includes(q.toLowerCase()));
function trackerShape(c){return {id:c.id||c.referenceId,category:c.category||'Official Correspondence',priority:normalizePriority(c.priority),sender:c.sender||c.senderEmail||'Not recorded',contact:c.senderEmail||'',receivedDate:String(c.receivedAt||c.createdAt||new Date().toISOString()).slice(0,10),eventDate:c.eventDate||'',subject:c.subject||'Untitled correspondence',remarks:c.description||c.remarks||'',status:statusList.includes(c.status)?c.status:(c.status==='Closed'?'Archived':'Pending'),sourceId:inferSourceId(c),attachmentLink:c.attachmentLink||c.AttachmentLink||c.Link||c.webUrl||c.documentUrl||'',source:c};}
export async function mount(el){hydrateGovernance();render(el);}
function render(el){const s=State.get(),u=UIState.get('correspondence',{q:'',status:'All',category:'All',page:1,size:25,selected:null,creating:false,tab:'tracker',md:'list',triage:false,source:'all'}),base=baseRows(s),recordsAll=base.map(trackerShape),records=filterItemsBySource(recordsAll,u.source||'all'),filtered=records.filter(r=>(u.status==='All'||r.status===u.status)&&(u.category==='All'||r.category===u.category)&&matches(r,u.q)),p=pageSlice(filtered,u.page,u.size),dupes=duplicateSummary(base),pending=records.filter(r=>r.status==='Pending'),events=records.filter(r=>r.category==='Event Invitation'),accepted=records.filter(r=>r.status==='Accepted'),high=records.filter(r=>isElevatedPriority(r.priority));el.innerHTML=`<div class="workspace cc-workspace correspondence-workspace"><div class="cc-controlbar"><div class="cc-metrics"><span class="cc-stat">Received <b>${records.length}</b></span><span class="cc-stat">Pending <b>${pending.length}</b></span><span class="cc-stat ok">Accepted <b>${accepted.length}</b></span><span class="cc-stat warn">High <b>${high.length}</b></span><span class="cc-stat dupe">Dupes <b>${dupes.count}</b></span></div><div class="cc-controls"><input data-q aria-label="Search correspondence records" placeholder="Search records, IDs, sender or reference" value="${esc(u.q)}"><select data-status aria-label="Filter by status"><option>All</option>${statusList.map(x=>`<option>${x}</option>`).join('')}</select><select data-category aria-label="Filter by category"><option>All</option>${categoryList.map(x=>`<option>${x}</option>`).join('')}</select><button class="btn" data-new data-create>Log New Memo</button><button class="btn ghost" data-tracker>Tracker</button><button class="btn ghost" data-emails>Emails (${s.emails.length})</button><button class="btn ghost" data-sync>Force Sync</button><button class="btn ghost" data-export>Export</button></div></div>${u.tab==='emails'?emailDesk(s):u.creating?createTrackerForm():trackerView(records,filtered,p,u,dupes,s)}</div>`;bind(el,s,u,base,records,filtered);}
function trackerView(records,filtered,p,u,dupes,s){const sel=records.find(r=>r.id===u.selected)||filtered[0];return `<div class="split correspondence-split" ${mdSwitch(sel?u.md:'list')}><div><div class="list-col">${p.rows.map(r=>`<article class="list-item ${sel&&r.id===sel.id?'active':''}" data-select="${esc(r.id)}"><div class="status-strip">${sourceBadge(r)} ${badge(r.status,r.status==='Pending'?'warn':r.status==='Declined'?'danger':r.status==='Accepted'?'ok':'')} ${badge(priorityLabel(r.priority),priorityTone(r.priority))}</div><h4>${esc(r.subject)}</h4><div class="meta">${esc(r.id)} · ${esc(r.sender)} · ${esc(r.receivedDate)}</div></article>`).join('')||'<div class="empty">No official records found.</div>'}</div>${pager(p)}</div><div class="detail-col panel-stack">${sel?trackerDetail(sel,s,u):'<section class="panel"><div class="empty"><h2>Select correspondence</h2></div></section>'}</div></div>`;}
function trackerDetail(r,s,u){const relTasks=relatedTasks(r,s), relEmails=relatedEmails(r,s);return `${mdBack('Back to tracker')}<section class="panel correspondence-detail-card"><div class="eyebrow panel-eyebrow">Record Details</div><h2 class="cc-detail-title">${esc(r.subject)}</h2><div class="status-strip">${sourceBadge(r)} ${badge(r.category)} ${badge(r.status)} ${badge(priorityLabel(r.priority),priorityTone(r.priority))}</div><dl class="detail-grid"><dt>Reference ID</dt><dd>${esc(r.id)}</dd><dt>Sender / MDA</dt><dd>${esc(r.sender)}</dd><dt>Received</dt><dd>${esc(r.receivedDate)}</dd><dt>Event date</dt><dd>${esc(r.eventDate||'—')}</dd><dt>Contact</dt><dd>${esc(r.contact||'—')}</dd></dl>${bodyBlock(r.remarks)}<div class="form-row record-action-grid"><button type="button" class="btn ${u.triage?'ghost':''}" data-triage-toggle>${u.triage?'Close triage form':'Triage / Update'}</button><button type="button" class="btn ghost" data-quick-accept="${esc(r.id)}">Mark Accepted</button><button type="button" class="btn ${u.assigning?'ghost':''}" data-assign-toggle>${u.assigning?'Close assignment':'Assign'}</button><button type="button" class="btn ghost" data-to-registry>Send to Registry</button><button type="button" class="btn ghost" data-document>Open Document</button><button type="button" class="btn danger" data-delete="${esc(r.id)}">Archive/Delete</button></div></section>${u.assigning?`<section class="panel"><div class="eyebrow panel-eyebrow">Assign this correspondence</div><p class="meta">Create a governed task from <b>${esc(r.subject)}</b> — category, DSU and assignee cascade automatically. Bulk assignment remains available separately.</p><div data-assign-host></div></section>`:''}${u.triage?`<section class="panel"><div class="eyebrow panel-eyebrow">Triage & Disposition</div><form class="grid" data-triage><label>Status<select name="status">${statusList.map(x=>`<option ${x===r.status?'selected':''}>${x}</option>`).join('')}</select></label><label>Priority<select name="priority">${priorityOptions(r.priority)}</select></label><label>Category<select name="category">${categoryList.map(x=>`<option ${x===r.category?'selected':''}>${x}</option>`).join('')}</select></label><label class="wide">Remarks<textarea name="remarks" rows="3">${esc(r.remarks)}</textarea></label><div class="wide form-row"><button class="btn">Save & Sync</button><button type="button" class="btn ghost" data-triage-cancel>Cancel</button></div></form></section>`:''}<section class="panel"><h3>Linked Execution Tasks (${relTasks.length})</h3>${relTasks.map(t=>`<div class="matrix-card"><b>${esc(t.title)}</b><div class="meta">${esc(t.status||'Pending')} · ${esc(t.assignedTo||'Unassigned')}</div></div>`).join('')||'<p class="meta">No tasks spawned from this lineage.</p>'}</section><section class="panel"><h3>Communication Threads (${relEmails.length})</h3>${relEmails.map(e=>`<div class="matrix-card"><b>${esc(e.subject)}</b><div class="meta">${esc(e.fromName||e.fromAddress||'—')} · ${esc(fmtDateTime(e.receivedDateTime||''))}</div></div>`).join('')||'<p class="meta">No correlated emails detected.</p>'}</section>`;}
function createTrackerForm(){return `<form class="panel grid" data-create-form><h2 class="wide">Log New Memo / Invite</h2><label>Category *<select name="category" required>${categoryList.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Priority Level *<select name="priority" required>${priorityOptions('normal')}</select></label><label>Sender / Organization / MDA *<input name="sender" required></label><label>Contact Email / Phone<input name="contact"></label><label>Date Received *<input name="receivedDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>Event Date<input name="eventDate" type="datetime-local"></label><label class="wide">Subject / Title *<input name="subject" required></label><label class="wide">Detailed Remarks / DG's Minute Notes<textarea name="remarks" rows="5"></textarea></label><label>Status<select name="status">${statusList.map(x=>`<option ${x==='Pending'?'selected':''}>${x}</option>`).join('')}</select></label><div class="wide form-row"><button class="btn">Save & Sync</button><button type="button" class="btn ghost" data-cancel>Clear Form</button></div></form>`;}
function emailDesk(s){return `<div class="panel"><div class="pagehead"><div><h2>Email intake workbench</h2><p class="subtitle">Convert relevant messages into governed correspondence.</p></div><button class="btn ghost" data-tracker>Back to tracker</button></div><div class="tablewrap dgo-table-wrap"><table class="dgo-table"><thead><tr><th>Received</th><th>From</th><th>Subject</th><th>Attachments</th><th>Action</th></tr></thead><tbody>${capRows(s.emails,RenderBudget.tableRows).map(e=>`<tr><td>${esc(fmtDateTime(e.receivedDateTime))}</td><td>${esc(e.fromName||e.fromAddress)}</td><td>${esc(e.subject)}</td><td>${e.hasAttachments?'Yes':'No'}</td><td><button class="btn ghost" data-email="${esc(e.id)}">Create correspondence</button></td></tr>`).join('')}</tbody></table></div></div>`;}
function bind(el,s,u,base,records,filtered){el.querySelectorAll('[data-source-view]').forEach(b=>b.onclick=()=>{UIState.set('correspondence',{source:b.dataset.sourceView,page:1});render(el)});el.querySelector('[data-status]')&&(el.querySelector('[data-status]').value=u.status);el.querySelector('[data-category]')&&(el.querySelector('[data-category]').value=u.category);el.querySelector('[data-status]')?.addEventListener('change',e=>{UIState.set('correspondence',{status:e.target.value,page:1});render(el)});el.querySelector('[data-category]')?.addEventListener('change',e=>{UIState.set('correspondence',{category:e.target.value,page:1});render(el)});debouncedInput(el.querySelector('[data-q]'),v=>{UIState.set('correspondence',{q:v,page:1});render(el)},{refind:()=>el.querySelector('[data-q]')});el.querySelector('[data-new]')?.addEventListener('click',()=>{UIState.set('correspondence',{creating:true,tab:'tracker'});render(el);resetWorkspaceScroll()});el.querySelectorAll('[data-tracker]').forEach(b=>b.onclick=()=>{UIState.set('correspondence',{tab:'tracker',creating:false});render(el);resetWorkspaceScroll()});el.querySelector('[data-emails]')?.addEventListener('click',()=>{UIState.set('correspondence',{tab:'emails',creating:false});render(el);resetWorkspaceScroll()});el.querySelectorAll('[data-select]').forEach(x=>x.onclick=()=>{UIState.set('correspondence',{selected:x.dataset.select,creating:false,md:'detail'});render(el);resetDetailScroll(el)});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('correspondence',{md:'list'});render(el)});el.querySelector('[data-triage-toggle]')?.addEventListener('click',()=>{UIState.set('correspondence',{triage:!u.triage});render(el)});el.querySelector('[data-triage-cancel]')?.addEventListener('click',()=>{UIState.set('correspondence',{triage:false});render(el)});el.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{UIState.set('correspondence',{page:+x.dataset.page});render(el)});el.querySelector('[data-cancel]')?.addEventListener('click',()=>{UIState.set('correspondence',{creating:false});render(el)});el.querySelector('[data-export]')?.addEventListener('click',()=>exportTracker(records));el.querySelector('[data-sync]')?.addEventListener('click',()=>forceSync());el.querySelector('[data-create-form]')?.addEventListener('submit',async e=>createRecord(e,base,s,el));el.querySelector('[data-triage]')?.addEventListener('submit',async e=>updateRecord(e,u.selected,base,s,el));el.querySelector('[data-quick-accept]')?.addEventListener('click',async e=>quickStatus(e.currentTarget.dataset.quickAccept,'Accepted',base,s,el));el.querySelector('[data-delete]')?.addEventListener('click',async e=>quickStatus(e.currentTarget.dataset.delete,'Archived',base,s,el));el.querySelector('[data-assign-toggle]')?.addEventListener('click',()=>{UIState.set('correspondence',{assigning:!u.assigning,triage:false});render(el)});el.querySelector('[data-to-registry]')?.addEventListener('click',()=>{State.patch({selectedId:u.selected});toast('Correspondence sent to Registry for registration','success');location.hash='#/registry'});const assignHost=el.querySelector('[data-assign-host]');if(assignHost){const sel=records.find(r=>r.id===u.selected)||filtered[0];if(sel){const src=sel.source||{};const item={...src,id:sel.id,title:sel.subject,referenceId:src.referenceId||sel.id,category:sel.category};mountAssignmentForm(assignHost,item,{guidance:false,onCancel:()=>{UIState.set('correspondence',{assigning:false});render(el)},onDone:()=>{UIState.set('correspondence',{assigning:false});toast('Task assigned from correspondence','success');render(el)}});}}el.querySelector('[data-document]')?.addEventListener('click',()=>{const sel=records.find(r=>String(r.id)===String(u.selected))||filtered[0];const link=sel&&(sel.attachmentLink||sel.source?.attachmentLink||sel.source?.AttachmentLink||sel.source?.Link);if(link){window.open(link,'_blank','noopener,noreferrer');toast('Opening source document','success');}else{toast('No source document is attached to this record','info');}});el.querySelectorAll('[data-email]').forEach(b=>b.onclick=()=>convertEmail(b.dataset.email,s,base,el));}
async function createRecord(e,base,s,el){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),id=`NITDA-${Date.now().toString().slice(-6)}`;const c={id,referenceId:id,subject:d.subject,sender:d.sender,senderEmail:d.contact,receivedAt:new Date(d.receivedDate).toISOString(),eventDate:d.eventDate,correspondenceType:'Incoming',channel:'Document',category:d.category,status:d.status,priority:normalizePriority(d.priority),confidentiality:'Official',description:d.remarks,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};if(!await confirmAction({title:'Confirm new correspondence',body:`<p>${esc(c.subject)}</p>${actionPreview({id,category:c.category,priority:c.priority,status:c.status})}`}))return;await executeOwnedAction('correspondence','create-correspondence',()=>{State.patch({correspondence:[c,...base],audit:[audit('Correspondence Logged','correspondence',id,{},s.profile.email),...s.audit]},{module:'correspondence',action:'tracker:create',ref:id});invoke('DYNAMIC_ACTIONS',{action:'upsert_record',module:'DGCEO_Tracker',data:c}).catch(()=>toast('Saved locally; synchronization queued','error'));},{ref:id});UIState.set('correspondence',{creating:false,selected:id});toast('Record saved successfully','success');render(el);}
async function updateRecord(e,id,base,s,el){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),r=base.find(x=>String(x.id)===String(id)||String(x.referenceId)===String(id));if(!r)return;if(!await confirmAction({title:'Confirm tracker update',body:`<p>${esc(r.subject)}</p>${actionPreview(d)}`}))return;await executeOwnedAction('correspondence','triage',()=>{const res=setCorrespondenceStatus({...s,correspondence:base},r.id,d.status,s.profile.email,{surface:'correspondence',extra:{priority:normalizePriority(d.priority),category:d.category,description:d.remarks}});if(!res)return;State.patch(res.patch,{module:'correspondence',action:'tracker:update',ref:id});invoke('DYNAMIC_ACTIONS',{action:'upsert_record',module:'DGCEO_Tracker',data:res.record}).catch(()=>toast('Saved locally; synchronization queued','error'));},{ref:id});UIState.set('correspondence',{triage:false});toast('Record updated successfully','success');render(el);}
async function quickStatus(id,status,base,s,el){const r=base.find(x=>String(x.id)===String(id)||String(x.referenceId)===String(id));if(!r)return;if(!await confirmAction({title:status==='Archived'?'Archive/delete official record':'Quick status update',body:`<p>${esc(r.subject)}</p><p>Status: ${esc(status)}</p>`}))return;await executeOwnedAction('correspondence','triage',()=>{const res=setCorrespondenceStatus({...s,correspondence:base},r.id,status,s.profile.email,{surface:'correspondence-quick-action'});if(!res)return;State.patch(res.patch,{module:'correspondence',action:'tracker:quick-action',ref:id});invoke('DYNAMIC_ACTIONS',{action:status==='Archived'?'delete_record':'update_status',data:{id,status}}).catch(()=>toast('Saved locally; synchronization queued','error'));},{ref:id});toast('Status successfully updated to '+status,'success');render(el);}
function exportTracker(records){if(!records.length)return toast('No data available to export','info');exportCsv(records,[{key:'id',label:'Reference_ID'},{key:'category',label:'Category'},{render:r=>priorityLabel(r.priority),label:'Priority'},{key:'status',label:'Status'},{key:'sender',label:'Sender_MDA'},{key:'subject',label:'Subject'},{key:'receivedDate',label:'ReceivedDate'},{key:'eventDate',label:'EventDate'}],`NITDA_DG_Records_${new Date().toISOString().slice(0,10)}.csv`);}
async function forceSync(){if(!await confirmAction({title:'Force Sync',body:'Synchronize current DG/CEO correspondence records through the governed endpoint path?',confirmText:'Force Sync',cancelText:'Cancel'}))return;try{await requestSync({source:'correspondence',mode:'endpoint',endpoint:'DYNAMIC_ACTIONS',payload:{action:'full_sync',module:'DGCEO_Tracker'}});toast('Database synchronization complete','success')}catch{toast('Sync request queued or unavailable','error')}}
function convertEmail(id,s,base,el){const e=s.emails.find(x=>x.id===id);if(!e)return;const c={id:crypto.randomUUID(),sourceId:e.id,referenceId:'',subject:e.subject,sender:e.fromName,senderEmail:e.fromAddress,receivedAt:e.receivedDateTime,correspondenceType:'Email',channel:'Email',category:'Official Correspondence',status:'Pending',priority:e.importance==='high'?'high':'normal',confidentiality:'Official',description:e.bodyPreview||e.bodyContent,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};executeOwnedAction('correspondence','convert-email',()=>State.patch({correspondence:[c,...base],audit:[audit('Email Converted','correspondence',c.id,{emailId:e.id},s.profile.email),...s.audit]},{module:'correspondence',action:'email:convert',ref:c.id}),{ref:c.id});UIState.set('correspondence',{tab:'tracker',selected:c.id});toast('Email converted to correspondence','success');render(el);}

