import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { status, makeRef } from '../core/domain.js';
import { updateTaskState, createTask } from '../core/enterprise-domain.js';
import { priorityOptions, priorityLabel } from '../config/priority.config.js';
import { sourceFilterChips } from '../core/source-views.js';
import { buildEmailTaskPayload, validateEmailTaskPayload, assignmentPreviewHtml } from '../core/assignment-payload.js';
import { debouncedInput } from '../core/ui-interactions.js';
import { head, esc, chips, badge, toast, confirmAction, mdBack, mdSwitch, resetDetailScroll,fmtDate,fmtDateTime, actionPreview} from '../core/ui.js';
import { invoke } from '../core/api.js';
import { UIState } from '../core/ui-state.js';
import { AssignmentCascade } from '../core/assignment-cascade.js';
const U=()=>UIState.get('lookup',{q:'',scope:'all',selType:'',selId:'',md:'list'});
let q='', scope='all', selected={type:'',id:''}, mdView='list';
function syncLocal(){const u=U();q=u.q;scope=u.scope;selected={type:u.selType,id:u.selId};mdView=u.md;}
const SCOPES=[{value:'all',label:'All'},{value:'activities',label:'Activities'},{value:'tasks',label:'Tasks'},{value:'emails',label:'Emails'},{value:'comments',label:'Comments'},{value:'approvals',label:'Approvals'}];
const ROUTE={activities:'activities',tasks:'orchestrator',comments:'comments',approvals:'approvals'};
const vec=v=>String(v||'').toLowerCase();
const hit=(...xs)=>!q||xs.some(x=>vec(x).includes(vec(q)));
function groups(s){const out={};if(scope==='all'||scope==='activities'){const rows=s.activities.filter(a=>hit(a.title,a.referenceId,status(a),a.category,a.assignedTo));if(rows.length)out.activities=rows}if(scope==='all'||scope==='tasks'){const rows=s.tracking.filter(t=>hit(t.title,t.referenceId,t.assignedTo,t.status,t.priority));if(rows.length)out.tasks=rows}if(scope==='all'||scope==='emails'){const rows=(s.emails||[]).filter(e=>hit(e.subject,e.bodyPreview,e.fromAddress,e.from));if(rows.length)out.emails=rows}if(scope==='all'||scope==='comments'){const rows=s.comments.filter(c=>hit(c.body,c.author,c.referenceId));if(rows.length)out.comments=rows}if(scope==='all'||scope==='approvals'){const rows=s.approvals.filter(a=>hit(a.title,a.ref,a.status));if(rows.length)out.approvals=rows}return out;}
function findItem(s){if(!selected.id)return null;return (selected.type==='activities'?s.activities:selected.type==='tasks'?s.tracking:selected.type==='emails'?(s.emails||[]):selected.type==='comments'?s.comments:s.approvals).find(x=>String(x.id)===String(selected.id));}
function item(type,r){const id=esc(r.id);if(type==='activities')return `<div class="list-item" data-type="activities" data-id="${id}"><h4>${esc(r.title)}</h4><div class="meta">${esc(r.referenceId||'—')} · ${esc(status(r))} · ${esc(r.category||'Unclassified')}</div></div>`;if(type==='tasks')return `<div class="list-item" data-type="tasks" data-id="${id}"><h4>${esc(r.title)}</h4><div class="meta">${esc(r.referenceId||'—')} · ${esc(r.assignedTo||'—')} · ${esc(r.status||'Pending')}</div></div>`;if(type==='emails')return `<div class="list-item" data-type="emails" data-id="${id}"><h4>${esc(r.subject||'No subject')}</h4><div class="meta">${esc(r.fromAddress||r.from||'—')} · ${esc(fmtDateTime(r.receivedDateTime||r.received||''))}</div></div>`;if(type==='comments')return `<div class="list-item" data-type="comments" data-id="${id}"><h4>${esc((r.body||'').slice(0,80))}</h4><div class="meta">${esc(r.author)} · ${esc(r.referenceId||'—')}</div></div>`;return `<div class="list-item" data-type="approvals" data-id="${id}"><h4>${esc(r.title)}</h4><div class="meta">${esc(r.ref||'—')} · ${esc(r.status)}</div></div>`;}

function emailCascadeFields(s, email){ const draft=AssignmentCascade.cascade({activity:{category:email.category||'General Administration'},state:s}); const cats=AssignmentCascade.categories(s), subs=AssignmentCascade.subcategories(draft.category,s), deps=AssignmentCascade.departments(s); return `<label>Category<select name="category"><option value="">Select category</option>${cats.map(c=>`<option value="${esc(c.category)}" ${c.category===draft.category?'selected':''}>${esc(c.category)}</option>`).join('')}</select></label><label>Subcategory<select name="subcategory"><option value="">Select subcategory</option>${subs.map(x=>`<option value="${esc(x.subcategory)}" ${x.subcategory===draft.subcategory?'selected':''}>${esc(x.subcategory)}</option>`).join('')}</select></label><label>Primary DSU<select name="dsu"><option value="">Select DSU</option>${deps.map(d=>`<option value="${esc(d.dsuKey)}" ${d.dsuKey===draft.dsu?'selected':''}>${esc(d.title||d.dsuKey)}</option>`).join('')}</select></label><label>Support DSU<select name="supportDsu"><option value="">Select support DSU</option>${deps.map(d=>`<option value="${esc(d.dsuKey)}" ${d.dsuKey===draft.supportDsu?'selected':''}>${esc(d.title||d.dsuKey)}</option>`).join('')}</select></label><label>Start date<input name="startDate" type="date" value="${esc(draft.startDate||'')}"></label><label>Ack due<input name="ack" type="date" value="${esc(draft.ack||'')}"></label><label>Due date<input name="due" type="date" value="${esc(draft.due||'')}"></label><label>Priority<select name="priority">${priorityOptions(draft.priority||email.importance||'normal')}</select></label><input type="hidden" name="categoryCode" value="${esc(draft.categoryCode||'')}"><input type="hidden" name="subcategoryCode" value="${esc(draft.subcategoryCode||'')}"><input type="hidden" name="supportingAssignee" value="${esc(draft.supportingAssignee||'')}"><input type="hidden" name="cascadeSnapshot" value="">`; }

function detail(s){const r=findItem(s);if(!r)return `<section class="panel"><div class="empty"><h2>No item selected</h2><p>Select an item or run a direct lookup.</p></div></section>`;if(selected.type==='activities')return `${mdBack('Back to results')}<section class="panel"><div class="eyebrow panel-eyebrow">Document Details</div><h2>${esc(r.title)}</h2><div class="status-strip">${badge(status(r))} ${badge(r.assignmentStatus||'Assignment pending')}</div><dl class="detail-grid"><dt>ID</dt><dd>${esc(r.id)}</dd><dt>Reference</dt><dd>${esc(r.referenceId||'—')}</dd><dt>Category</dt><dd>${esc(r.category||'—')}</dd><dt>Assigned To</dt><dd>${esc(r.assignedTo||'—')}</dd><dt>Created</dt><dd>${esc(fmtDateTime(r.created||''))}</dd></dl>${r.flags?.length?`<div class="chips">${r.flags.map(f=>`<span class="chip">⚑ ${esc(f.flag)} · ${esc(fmtDate(f.at||''))}</span>`).join('')}</div>`:''}</section><section class="panel"><div class="eyebrow panel-eyebrow">Direct Actions</div><div class="form-row"><button class="btn" data-assign>Assign</button><button class="btn ghost" data-flag="dg">DG Attention</button><button class="btn ghost" data-flag="followup">Follow-Up</button><button class="btn ghost" data-flag="int">INT</button><button class="btn ghost" data-flag="unc">UNC</button></div></section>`;if(selected.type==='tasks')return `${mdBack('Back to results')}<section class="panel"><div class="eyebrow panel-eyebrow">Task Details</div><h2>${esc(r.title)}</h2><div class="status-strip">${badge(r.status||'Pending')} ${badge(r.priority||'normal')}</div><dl class="detail-grid"><dt>ID</dt><dd>${esc(r.id)}</dd><dt>Reference</dt><dd>${esc(r.referenceId||'—')}</dd><dt>Owner</dt><dd>${esc(r.assignedTo||'—')}</dd><dt>Due</dt><dd>${esc(fmtDate(r.due||'—'))}</dd></dl></section><section class="panel"><div class="eyebrow panel-eyebrow">Governed Update</div><form class="grid" data-update-task><label>Progress<select name="status"><option>Not started</option><option>In progress</option><option>Completed</option><option>Deferred</option></select></label><label>Priority<select name="priority">${priorityOptions(r.priority)}</select></label><label class="wide">Comments<textarea name="comments" rows="3"></textarea></label><div class="wide"><button class="btn">Preview & Submit Update</button></div></form></section>`;if(selected.type==='emails')return `${mdBack('Back to results')}<section class="panel"><div class="eyebrow panel-eyebrow">Email Details</div><h2>${esc(r.subject||'No subject')}</h2><dl class="detail-grid"><dt>From</dt><dd>${esc(r.fromAddress||r.from||'—')}</dd><dt>Received</dt><dd>${esc(fmtDateTime(r.receivedDateTime||r.received||''))}</dd><dt>Attachments</dt><dd>${r.hasAttachments?'Yes':'No'}</dd></dl><form class="grid" data-email-task-form><label class="wide">Task title<input name="title" value="${esc(r.subject||'Email task')}" required></label><label>Assigned to<input name="assignedTo" type="email" value="${esc(State.get().profile.email||'')}" required></label>${emailCascadeFields(State.get(), r)}<label class="wide">CC recipients<input name="copy" placeholder="email1; email2"></label><label class="wide">Instruction<textarea name="comments" rows="3">${esc(r.bodyPreview||'')}</textarea></label><div class="wide form-row"><button class="btn">Create task from email · Preview & Create Task</button></div></form></section><section class="panel"><div class="eyebrow panel-eyebrow">Message Body</div><div class="email-frame"><iframe sandbox="allow-same-origin" srcdoc="${esc(r.bodyContent||r.body||r.bodyPreview||'')}"></iframe></div></section>`;return `${mdBack('Back to results')}<section class="panel"><h2>${esc(r.title||r.body||'Item')}</h2>${actionPreview(r)}</section>`;}
export async function mount(el){hydrateGovernance();render(el);}

function render(el){syncLocal();const s=State.get(),g=groups(s),total=Object.values(g).reduce((n,r)=>n+r.length,0);el.innerHTML=`<div class="workspace">${head('Lookup & Direct Action','Single-item lookup across documents, tasks and emails with governed flag, update and create-task actions.')}
<section class="panel lookup-direct"><div class="toolbar"><input data-q placeholder="Enter ID, reference, title or email subject" value="${esc(q)}"><select data-scope-select>${SCOPES.map(x=>`<option value="${x.value}">${x.label}</option>`).join('')}</select><button class="btn" data-direct>Direct Lookup</button><button class="btn ghost" data-back>Reset</button></div>${chips(SCOPES,scope,'data-scope')}</section>
<div class="split" ${mdSwitch(selected.id?mdView:'list')}><section class="panel"><div class="eyebrow">Results (${total})</div>${!q?'<p class="meta">Start typing or choose Direct Lookup for an endpoint-backed search.</p>':(!total?`<p class="meta">No local results for "${esc(q)}".</p>`:Object.entries(g).map(([type,rows])=>`<div class="result-group"><div class="eyebrow">${esc(type.toUpperCase())} (${rows.length})</div><div class="list-col">${rows.slice(0,80).map(r=>item(type,r)).join('')}</div></div>`).join(''))}</section><div class="detail-col panel-stack">${detail(s)}</div></div></div>`;
el.querySelector('[data-scope-select]').value=scope;debouncedInput(el.querySelector('[data-q]'),v=>{UIState.set('lookup',{q:v});render(el)},{delay:120,refind:()=>el.querySelector('[data-q]')});el.querySelector('[data-scope-select]').onchange=e=>{UIState.set('lookup',{scope:e.target.value});render(el)};el.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{UIState.set('lookup',{scope:b.dataset.scope});render(el)});el.querySelector('[data-back]').onclick=()=>{UIState.set('lookup',{q:'',selType:'',selId:'',md:'list'});render(el)};el.querySelector('[data-direct]').onclick=async()=>directLookup(el);el.querySelectorAll('[data-type][data-id]').forEach(c=>c.onclick=()=>{UIState.set('lookup',{selType:c.dataset.type,selId:c.dataset.id,md:'detail'});render(el);resetDetailScroll(el)});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('lookup',{md:'list'});render(el)});el.querySelector('[data-assign]')?.addEventListener('click',()=>{State.patch({selectedId:selected.id});location.hash='#/single-assignment'});el.querySelectorAll('[data-flag]').forEach(b=>b.onclick=()=>flagActivity(b.dataset.flag));el.querySelector('[data-update-task]')?.addEventListener('submit',updateTask);el.querySelector('[data-email-task-form]')?.addEventListener('submit',createTaskFromEmail);}
async function directLookup(el){if(!q)return toast('Enter an ID, reference or title first','error');const qtype=scope==='tasks'?'FETCH_ACTIVITIES':scope==='emails'?'SUBSIDIARY_ACTIONS':'GET_DOCS';if(!await confirmAction({title:'Confirm direct lookup',body:`<p>Lookup <b>${esc(q)}</b> in ${esc(scope)}.</p>${actionPreview({query:q,scope})}`,confirmText:'Run lookup',cancelText:'Cancel'}))return;try{const {requestSync}=await import('../core/data-loader.js');await requestSync({source:'lookup',mode:'endpoint',endpoint:qtype,payload:{operation:'read',mode:'single',query:q,scope}});toast('Lookup request sent; synchronize results from Operator HUD if needed','success')}catch{toast('Endpoint unavailable; local search remains active','error')}}
async function flagActivity(flag){syncLocal();const s=State.get(),a=s.activities.find(x=>String(x.id)===String(selected.id));if(!a)return;if(!await confirmAction({title:'Confirm document flag',body:`<p>${esc(a.title)}</p><p>Flag: <b>${esc(flag)}</b></p>`,confirmText:'Submit flag',cancelText:'Cancel'}))return;const now=new Date().toISOString();await executeOwnedAction('lookup','flag-document',()=>{State.patch({activities:s.activities.map(x=>x.id===a.id?{...x,flags:[...(x.flags||[]),{flag,at:now,by:s.profile.email}]}:x)},{module:'lookup',action:'flag-document',ref:a.referenceId||String(a.id)});invoke('DYNAMIC_ACTIONS',{action:'flagDocument',flag,activityId:a.id,title:a.title}).catch(()=>toast('Flag recorded locally; sync queued','error'));},{ref:a.referenceId||String(a.id)});toast('Flag recorded','success');}
async function updateTask(e){e.preventDefault();syncLocal();const d=Object.fromEntries(new FormData(e.target)),s=State.get(),t=s.tracking.find(x=>String(x.id)===String(selected.id));if(!t)return;if(!await confirmAction({title:'Confirm task update',body:`<p>${esc(t.title)}</p>${actionPreview({before:{status:t.status,priority:priorityLabel(t.priority)},after:{status:d.status,priority:priorityLabel(d.priority)}})}`,confirmText:'Submit update',cancelText:'Cancel'}))return;await executeOwnedAction('lookup','update-task',()=>{const r=updateTaskState(s,t.id,{status:d.status,priority:d.priority},s.profile.email,{surface:'lookup'});const note=String(d.comments||'').trim();const patch=note?{...r.patch,comments:[{id:crypto.randomUUID(),referenceId:t.referenceId||String(t.id),body:note,author:s.profile.email,ts:new Date().toISOString(),type:'task-update'},...s.comments]}:r.patch;State.patch(patch,{module:'lookup',action:'update-task',ref:t.referenceId||''});invoke('DYNAMIC_ACTIONS',{action:'updateTask',task:r.task}).catch(()=>toast('Task update saved locally; sync queued','error'));},{ref:t.referenceId||''});toast('Task updated','success');}
async function createTaskFromEmail(ev){ev?.preventDefault?.();syncLocal();const s=State.get(),e=(s.emails||[]).find(x=>String(x.id)===String(selected.id));if(!e)return;const form=ev?.target?Object.fromEntries(new FormData(ev.target)):{title:e.subject||'Email task',assignedTo:s.profile.email,priority:'normal',comments:e.bodyPreview||''};const ref=makeRef(e.id||Date.now(),'EMAIL','TASK');const payload=buildEmailTaskPayload({email:e,form,actor:s.profile,referenceId:ref});const errors=validateEmailTaskPayload(payload);if(errors.length)return toast(errors.join('; '),'error');if(!await confirmAction({title:'Preview & create task from email',body:`<p>${esc(payload.title)}</p>${assignmentPreviewHtml(payload)}`,confirmText:'Create task',cancelText:'Cancel'}))return;await executeOwnedAction('lookup','create-task-from-email',()=>{const r=createTask(s,{title:payload.title,referenceId:ref,assignedTo:payload.assignedTo,assignedToDsu:payload.assignedToDsu||payload.dsu,priority:payload.priority,due:payload.due,description:payload.instruction,sourceEmailId:e.id},s.profile.email,{surface:'email-to-task'});const task={...r.task,category:payload.category,ccRecipients:payload.ccRecipients,sourceEmailId:e.id,emailSubject:e.subject||'',emailFrom:e.fromAddress||e.from||''};State.patch({...r.patch,tracking:[task,...(s.tracking||[])]},{module:'lookup',action:'create-task-from-email',ref});invoke('EMAIL_RELATED_TASK',{source:'email',email:e,tracking:task,payload}).catch(()=>toast('Task created locally; email-task sync queued','error'));},{ref,meta:{sourceEmailId:e.id,preview:true}});toast('Task created from email','success');render(document.querySelector('#app main')||document.body)}

