import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { ArchiveService } from '../core/archive.js';
import { debouncedInput } from '../core/ui-interactions.js';
import { priorityOptions } from '../config/priority.config.js';
import{State}from'../core/state.js';import{head,kpis,esc,badge,toast,confirmAction,mdBack,mdSwitch,resetDetailScroll}from'../core/ui.js';import{UIState,pageSlice,pager}from'../core/ui-state.js';import{createRegistryFile,createMovement,audit,RegistryStates}from'../core/enterprise-domain.js';import{invoke}from'../core/api.js';
export async function mount(el){hydrateGovernance();render(el)}
function render(el){const s=State.get(),u=UIState.get('registry',{q:'',queue:'All',page:1,size:25,selected:null,md:'list',routing:false}),files=s.registryFiles||[],candidate=s.correspondence.find(c=>String(c.id)===String(s.selectedId)||c.referenceId===s.selectedId),rows=files.filter(f=>(u.queue==='All'||f["status"] ===u.queue)&&(!u.q||[f.registryNumber,f.referenceId,f.subject,f.sender,f.currentHolder,f.currentDsu].some(v=>String(v||'').toLowerCase().includes(u.q.toLowerCase())))),p=pageSlice(rows,u.page,u.size),sel=files.find(x=>x.id===u.selected)||files.find(x=>x.correspondenceId===candidate?.id),movements=sel?s.fileMovements.filter(x=>x.registryFileId===sel.id):[],minutes=sel?s.registryMinutes.filter(x=>x.registryFileId===sel.id):[];el.innerHTML=`<div class="workspace">${head('Registry','Official registration, file jacket, custody chain, minutes, movement, queues, closure and archive control.')}${kpis([['Registered files',files.length],['In movement',files.filter(x=>['Routed','Received','Awaiting Collection'].includes(x.status)).length],['Awaiting receipt',s.fileMovements.filter(x=>x["status"] ==='Routed').length],['Archived',files.filter(x=>x["status"] ==='Archived').length]])}<div class="toolbar"><input data-q value="${esc(u.q)}" placeholder="Search registry no., reference, subject or holder"><select data-queue><option>All</option>${RegistryStates.map(x=>`<option>${x}</option>`).join('')}</select>${candidate&&!files.some(x=>x.correspondenceId===candidate.id)?'<button class="btn" data-register>Register selected correspondence</button>':''}<button class="btn ghost" data-unregistered>Unregistered queue</button></div><div class="split" ${mdSwitch(sel?u.md:'list')}><div><div class="list-col">${p.rows.map(f=>`<article class="list-item ${f.id===sel?.id?'active':''}" data-select="${esc(f.id)}"><div>${badge(f.status)}</div><h4>${esc(f.registryNumber)} · ${esc(f.subject)}</h4><div class="meta">${esc(f.referenceId||'No external reference')} · Holder: ${esc(f.currentHolder)}</div></article>`).join('')||'<div class="empty">No registry files in this queue.</div>'}</div>${pager(p)}</div><div class="detail-col panel-stack">${sel?jacket(sel,movements,minutes,s,u):`<section class="panel">${unregisteredQueue(s)}</section>`}</div></div></div>`;bind(el,s,u,files,sel,candidate,movements)}
function jacket(f,moves,minutes,s,u){const corr=s.correspondence.find(x=>x.id===f.correspondenceId),ops=s.operations.filter(x=>x.referenceId===f.referenceId);return`${mdBack('Back to registry queue')}<section class="panel"><div class="eyebrow panel-eyebrow">File Jacket</div><div class="status-strip">${badge(f.status)} ${badge(f.securityClass)}</div><h2>${esc(f.registryNumber)}</h2><h3>${esc(f.subject)}</h3><dl class="detail-grid"><dt>Reference</dt><dd>${esc(f.referenceId||'—')}</dd><dt>Registered</dt><dd>${esc(f.registeredAt)} by ${esc(f.registeredBy)}</dd><dt>Current holder</dt><dd>${esc(f.currentHolder)}</dd><dt>Current DSU</dt><dd>${esc(f.currentDsu)}</dd><dt>Retention</dt><dd>${esc(f.retentionClass)}</dd><dt>Source</dt><dd>${corr?'Correspondence linked':'Source unavailable'}</dd></dl><div class="chips"><span class="chip">${moves.length} movement(s)</span><span class="chip">${minutes.length} minute(s)</span><span class="chip">${ops.length} task(s)</span><span class="chip">${s.comments.filter(x=>x.referenceId===f.referenceId).length} comment(s)</span></div><div class="form-row"><button type="button" class="btn ${u.routing?'ghost':''}" data-route-toggle>${u.routing?'Close minute form':'Minute / Route file'}</button>${moves.some(x=>x["status"] ==='Routed')?'<button type="button" class="btn ghost" data-receive>Record receipt</button>':''}<button type="button" class="btn ghost" data-close-file>Close file</button><button type="button" class="btn ghost" data-archive-file>Archive file</button></div></section>${u.routing?`<section class="panel"><form class="grid" data-route><h3 class="wide">Constitute minute and route</h3><label>Route from<input name="from" value="${esc(f.currentHolder)}" required></label><label>Route to<input name="to" list="reg-dest" required><datalist id="reg-dest">${s.departments.map(d=>`<option value="${esc(d.title||d.dsuKey)}">${esc(d.email)}</option>`).join('')}${s.users.slice(0,300).map(u=>`<option value="${esc(u.email)}">${esc(u.fullName)}</option>`).join('')}</datalist></label><label>Action<select name="action"><option>FOR_ACTION</option><option>FOR_ATTENTION</option><option>FOR_REVIEW</option><option>FOR_DG_ATTENTION</option><option>COMPLY</option><option>FILE</option></select></label><label>Priority<select name="priority">${priorityOptions('normal')}</select></label><label class="wide">Official minute<textarea name="minute" rows="4" required></textarea></label><div class="wide form-row"><button class="btn">Record minute and route</button><button type="button" class="btn ghost" data-route-cancel>Cancel</button></div></form></section>`:''}<section class="panel"><h3>Custody and movement chain</h3><ul class="timeline">${moves.map(m=>`<li><div class="when">${esc(m.releasedAt)}${m.receivedAt?' → '+esc(m.receivedAt):''}</div><b>${esc(m.from)} → ${esc(m.to)} · ${esc(m.action)}</b><p>${esc(m.minute)}</p><div class="meta">${esc(m.status)}${m.receivedBy?' · received by '+esc(m.receivedBy):''}</div></li>`).join('')||'<li>No movement recorded.</li>'}</ul></section>`}
function unregisteredQueue(s){const rows=s.correspondence.filter(c=>!s.registryFiles.some(f=>f.correspondenceId===c.id));return`<h2>Unregistered correspondence</h2><p class="meta">${rows.length} item(s) await formal registration.</p>${rows.slice(0,30).map(c=>`<div class="action-row"><span><b>${esc(c.subject)}</b><small>${esc(c.referenceId||'No reference')} · ${esc(c.receivedAt)}</small></span><button class="btn ghost" data-register-id="${esc(c.id)}">Register</button></div>`).join('')||'<p>All correspondence is registered.</p>'}`}
function bind(el,s,u,files,sel,candidate,moves){el.querySelector('[data-queue]').value=u.queue;el.querySelector('[data-queue]').onchange=e=>{UIState.set('registry',{queue:e.target.value,page:1});render(el)};debouncedInput(el.querySelector('[data-q]'),v=>{UIState.set('registry',{q:v,page:1});render(el)},{refind:()=>el.querySelector('[data-q]')});el.querySelectorAll('[data-select]').forEach(x=>x.onclick=()=>{UIState.set('registry',{selected:x.dataset.select,md:'detail'});render(el);resetDetailScroll(el)});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('registry',{md:'list'});render(el)});el.querySelector('[data-route-toggle]')?.addEventListener('click',()=>{UIState.set('registry',{routing:!u.routing});render(el)});el.querySelector('[data-route-cancel]')?.addEventListener('click',()=>{UIState.set('registry',{routing:false});render(el)});el.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{UIState.set('registry',{page:+x.dataset.page});render(el)});const register=c=>executeOwnedAction('registry','register-file',()=>{const f=createRegistryFile(c,s.profile.email);State.patch({registryFiles:[f,...files],correspondence:s.correspondence.map(x=>x.id===c.id?{...x,status:'Classified',referenceId:x.referenceId||f.registryNumber}:x),audit:[audit('File Registered','registryFile',f.id,{registryNumber:f.registryNumber},s.profile.email),...s.audit]},{module:'registry',action:'registry:register',ref:f.registryNumber});UIState.set('registry',{selected:f.id,md:'detail'});toast('Official file registered','success');render(el)},{ref:c.referenceId||String(c.id)});el.querySelector('[data-register]')?.addEventListener('click',()=>register(candidate));el.querySelectorAll('[data-register-id]').forEach(b=>b.onclick=()=>register(s.correspondence.find(x=>x.id===b.dataset.registerId)));el.querySelector('[data-route]')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(!await confirmAction({title:'Record official minute and route',body:`<p>${esc(sel.registryNumber)}</p><p>${esc(d.from)} → ${esc(d.to)}</p><p>${esc(d.minute)}</p>`}))return;await executeOwnedAction('registry','route-file',()=>{const m=createMovement(sel,{...d,by:s.profile.email}),minute={id:crypto.randomUUID(),registryFileId:sel.id,registryNumber:sel.registryNumber,referenceId:sel.referenceId,text:d.minute,action:d.action,priority:d.priority,routeTo:d.to,by:s.profile.email,at:new Date().toISOString()};const updated={...sel,status:'Routed',currentHolder:d.to,currentDsu:d.to};State.patch({registryFiles:files.map(x=>x.id===sel.id?updated:x),fileMovements:[m,...s.fileMovements],registryMinutes:[minute,...s.registryMinutes],audit:[audit('File Routed','registryFile',sel.id,{movementId:m.id,to:d.to},s.profile.email),...s.audit]},{module:'registry',action:'registry:route',ref:sel.registryNumber});invoke('DYNAMIC_ACTIONS',{action:'route',ref:sel.referenceId||sel.registryNumber,to:d.to,minute:d.minute,priority:d.priority}).catch(()=>toast('Recorded locally; synchronization queued','error'));},{ref:sel.registryNumber});UIState.set('registry',{routing:false});toast('Minute recorded and file routed','success');render(el)});el.querySelector('[data-receive]')?.addEventListener('click',async()=>{const m=moves.find(x=>x["status"] ==='Routed');if(!m)return;if(!await confirmAction({title:'Confirm receipt',body:`<p>${esc(m.to)} acknowledges custody of ${esc(sel.registryNumber)}</p>`}))return;await executeOwnedAction('registry','receive-file',()=>{State.patch({fileMovements:s.fileMovements.map(x=>x.id===m.id?{...x,status:'Received',receivedAt:new Date().toISOString(),receivedBy:s.profile.email}:x),registryFiles:files.map(x=>x.id===sel.id?{...x,status:'Received'}:x),audit:[audit('Custody Received','registryFile',sel.id,{movementId:m.id},s.profile.email),...s.audit]},{module:'registry',action:'registry:receive',ref:sel.registryNumber});},{ref:sel.registryNumber});toast('Receipt and custody recorded','success');render(el)});for(const [attr,status] of [['data-close-file','Closed'],['data-archive-file','Archived']])el.querySelector(`[${attr}]`)?.addEventListener('click',async()=>{if(!await confirmAction({title:`${status} official file`,body:`<p>${esc(sel.registryNumber)}</p>${status==='Archived'?'<p>An immutable evidence bundle will be constituted for this reference.</p>':''}`}))return;const at=new Date().toISOString();await executeOwnedAction('registry',status==='Closed'?'close-file':'archive-file',async()=>{let bundleNote={};if(status==='Archived'){try{await ArchiveService.archiveReference(sel.referenceId||sel.registryNumber,s.profile,{closureSummary:`Registry file ${sel.registryNumber} archived`});bundleNote={archiveBundle:'created'};}catch(err){bundleNote={archiveBundle:'unavailable',reason:err.message};toast('Archived in registry; evidence bundle deferred: '+err.message,'info');}}State.patch({registryFiles:files.map(x=>x.id===sel.id?{...x,status,...(status==='Closed'?{closedAt:at}:{archivedAt:at})}:x),audit:[audit(`File ${status}`,'registryFile',sel.id,bundleNote,s.profile.email),...s.audit]},{module:'registry',action:'registry:'+status.toLowerCase(),ref:sel.registryNumber});},{ref:sel.registryNumber});toast(`File ${status.toLowerCase()}`,'success');render(el)})}

