import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { status, isComplete, isPendingStatus } from '../core/domain.js';
import { acknowledgeTask } from '../core/enterprise-domain.js';
import { exportCsv } from '../core/report-export-service.js';
import { relatedEmails as relatedEmailsFor } from '../core/data-selectors.js';
import { debouncedInput } from '../core/ui-interactions.js';
import { head, esc, table, chips, toast, confirmAction, badge, mdBack, mdSwitch, resetDetailScroll,fmtDate,fmtDateTime} from '../core/ui.js';
import { invoke } from '../core/api.js';
import { UIState } from '../core/ui-state.js';
import { inferSourceId, filterItemsBySource, sourceFilterChips, sourceBadge } from '../core/source-views.js';
let tab='matrix', query='', selectedId='';
let mdView='list';
let sourceView='all';
function syncLocal(){const u=UIState.get('response-tracking',{tab:'matrix',query:'',selected:'',md:'list',source:'all'});tab=u.tab;query=u.query;selectedId=u.selected;mdView=u.md;sourceView=u.source||'all';}
const normStatus=x=>String(x||'Pending');
const isPending=x=>isPendingStatus(normStatus(x));
function matrixRows(s){return s.tracking.map(t=>{const ref=String(t.referenceId||t.RefIDD||t.Reference_ID||'');const doc=s.activities.find(a=>String(a.id)===ref||String(a.referenceId)===ref);const relEmails=relatedEmailsFor({referenceId:ref,title:t.title},s);const start=t.start||t.created||t.Created||new Date().toISOString();const due=t.due||t.DueDate||'';let derived=t.status||t.Progress||'Pending';let slaPercent=0;if(due){const total=new Date(due)-new Date(start);const elapsed=Date.now()-new Date(start);slaPercent=Math.max(0,Math.min(100,(elapsed/(total||1))*100));if(!isComplete(derived)&&new Date(due)<new Date())derived='Overdue';}return{...t,sourceId:inferSourceId({...t,parentDoc:doc,relatedEmails:relEmails}),__id:String(t.id),referenceId:ref||'—',title:t.title||t.Title||'Untitled task',assignedTo:t.assignedTo||t.AssignedTo||'N/A',category:t.category||t.Classification||doc?.category||'Standard',derivedStatus:derived,slaPercent,parentDoc:doc,relatedEmails:relEmails};});}
function rowsFor(s){if(tab==='matrix')return matrixRows(s);if(tab==='all')return s.activities.map(a=>({referenceId:a.referenceId||'—',title:a.title,status:status(a),category:a.category||'—',created:fmtDate(a.created),__id:a.id,__route:'activities'}));if(tab==='tasks')return s.tracking.map(t=>({referenceId:t.referenceId||'—',title:t.title,assignedTo:t.assignedTo||'—',priority:t.priority||'normal',status:t.status,__id:t.id,__route:'orchestrator'}));if(tab==='comments')return s.comments.map(c=>({referenceId:c.referenceId||'—',author:c.author||'—',body:(c.body||'').slice(0,60),ts:fmtDate(c.ts||''),__id:c.id,__route:'comments'}));return s.activities.filter(a=>s.tracking.some(t=>t.referenceId===a.referenceId)).map(a=>{const t=s.tracking.find(t=>t.referenceId===a.referenceId);return{referenceId:a.referenceId,doc:a.title,task:t.title,status:t.status,__id:a.id,__route:'activities'}});}
function colsFor(){if(tab==='matrix')return[{key:'referenceId',label:'Trace ID'},{key:'title',label:'Execution Node'},{key:'assignedTo',label:'Executor'},{key:'category',label:'Classification'},{key:'derivedStatus',label:'Governance'}];if(tab==='all')return[{key:'referenceId',label:'Reference'},{key:'title',label:'Title'},{key:'status',label:'Status'},{key:'category',label:'Category'},{key:'created',label:'Date'}];if(tab==='tasks')return[{key:'referenceId',label:'Reference'},{key:'title',label:'Title'},{key:'assignedTo',label:'Assigned To'},{key:'priority',label:'Priority'},{key:'status',label:'Status'}];if(tab==='comments')return[{key:'referenceId',label:'Reference'},{key:'author',label:'Author'},{key:'body',label:'Comment'},{key:'ts',label:'Date'}];return[{key:'referenceId',label:'Reference'},{key:'doc',label:'Document'},{key:'task',label:'Task'},{key:'status',label:'Status'}];}
function metric(s){const rows=matrixRows(s);return{total:rows.length,overdue:rows.filter(r=>r.derivedStatus==='Overdue').length,pending:rows.filter(r=>isPending(r.derivedStatus)).length,completed:rows.filter(r=>isComplete(r.derivedStatus)).length};}
function exportRows(rows,cols){exportCsv(rows,cols,`response-tracking-${tab}.csv`);}
function minuteTrace(item){const entries=[];if(item.parentDoc)entries.push({by:'Registry',text:`Registry Receipt: Document ${item.parentDoc.id||item.parentDoc.ID||''} registered into system context.`,date:item.parentDoc.created||item.parentDoc.Created});entries.push({by:'Workflow Engine',text:`Task node initialized for ${item.assignedTo}. Instruction: ${item.description||item.Description||'Execute as per NITDA operational standards.'}`,date:item.created||item.Created||new Date().toISOString()});(item.relatedEmails||[]).forEach(e=>entries.push({by:'Email Gateway',text:`Matrix sibling email captured: ${e.subject||'No subject'} · ${(e.bodyPreview||'No preview').slice(0,160)}`,date:e.receivedDateTime||e.received||''}));return `<div class="minute-sheet">${entries.map((e,i)=>`<article class="minute-entry"><div class="meta">Minute ${i+1} · ${esc(fmtDateTime(e.date||''))}</div><p class="${/urgent|overdue/i.test(e.text)?'red-ink':'blue-ink'}">${esc(e.text)}</p><div class="signature">// Digitally Signed: ${esc(e.by)}</div></article>`).join('')}</div>`;}
function detailPanel(item,s){if(!item)return'<section class="panel"><div class="empty"><h2>Select a matrix row</h2><p>Open lineage, SLA and minute trace details.</p></div></section>';return`${mdBack('Back to matrix')}<section class="panel"><div class="eyebrow panel-eyebrow">Trace Details</div><div class="status-strip">${sourceBadge(item)} ${badge(item.derivedStatus,item.derivedStatus==='Overdue'?'danger':isComplete(item.derivedStatus)?'ok':'warn')} ${badge(Math.round(item.slaPercent||0)+'% SLA')}</div><h2>${esc(item.title)}</h2><dl class="detail-grid"><dt>Reference</dt><dd>${esc(item.referenceId)}</dd><dt>Executor</dt><dd>${esc(item.assignedTo)}</dd><dt>Category</dt><dd>${esc(item.category)}</dd><dt>Parent document</dt><dd>${item.parentDoc?esc(item.parentDoc.title):'—'}</dd><dt>Emails linked</dt><dd>${item.relatedEmails?.length||0}</dd></dl><div class="form-row"><button class="btn" data-ack="${esc(item.__id)}">Acknowledge</button><button class="btn ghost" data-forward="${esc(item.__id)}">Forward to Registry</button><button class="btn ghost" data-open-task="${esc(item.__id)}">Open task</button></div></section><section class="panel"><h3>Minute Sheet & Movement Record</h3>${minuteTrace(item)}</section>`;}
export async function mount(el){hydrateGovernance();render(el);}
function render(el){syncLocal();const s=State.get();const unfiltered=rowsFor(s);const all=filterItemsBySource(unfiltered,sourceView).filter(r=>!query||JSON.stringify(r).toLowerCase().includes(query.toLowerCase()));const cols=colsFor();const m=metric(s);const selected=matrixRows(s).find(x=>x.__id===selectedId)||matrixRows(s)[0];if(!selectedId&&selected){selectedId=selected.__id;UIState.set('response-tracking',{selected:selectedId});}el.innerHTML=`<div class="workspace rt-workspace">${head('Response Tracking','Enterprise response matrix, SLA health, lineage, acknowledgment and minute trace.')}
<div class="kpis"><div class="kpi"><small>Total Items</small><b>${m.total}</b></div><div class="kpi"><small>Overdue</small><b>${m.overdue}</b></div><div class="kpi"><small>Awaiting Action</small><b>${m.pending}</b></div><div class="kpi"><small>Completed</small><b>${m.completed}</b></div></div>
<section class="rt-filters">${sourceFilterChips(sourceView,'data-source-view',unfiltered)}<div class="toolbar rt-toolbar">${chips([{value:'matrix',label:'Matrix'},{value:'all',label:`All (${s.activities.length})`},{value:'tasks',label:`Tasks (${s.tracking.length})`},{value:'comments',label:`Comments (${s.comments.length})`},{value:'linked',label:'Linked'}],tab,'data-tab')}<input data-query value="${esc(query)}" placeholder="Search Ref ID, task title, assigned officer..."><button class="btn ghost" data-export>Export CSV</button></div></section>
<div class="split rt-split" ${mdSwitch(tab==='matrix'&&selected?mdView:'list')}><div class="panel matrix-list" data-runtime-list>${table(cols,all,r=>`data-id="${esc(r.__id)}" data-route="${esc(r.__route||'orchestrator')}" class="row-link ${tab==='matrix'&&r.__id===selectedId?'row-active':''}"`)}</div><div class="detail-col panel-stack" data-runtime-detail>${detailPanel(selected,s)}</div></div></div>`;
el.querySelectorAll('[data-source-view]').forEach(b=>b.onclick=()=>{UIState.set('response-tracking',{source:b.dataset.sourceView,selected:'',md:'list'});render(el)});el.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{UIState.set('response-tracking',{tab:b.dataset.tab});render(el)});debouncedInput(el.querySelector('[data-query]'),v=>{UIState.set('response-tracking',{query:v});render(el)},{refind:()=>el.querySelector('[data-query]')});el.querySelector('[data-export]').onclick=()=>all.length?exportRows(all,cols):toast('Nothing to export','error');el.querySelectorAll('tbody tr').forEach(tr=>tr.onclick=()=>{if(tab==='matrix'){UIState.set('response-tracking',{selected:tr.dataset.id,md:'detail'});render(el);resetDetailScroll(el)}else{State.patch({selectedId:tr.dataset.id});location.hash='#/'+tr.dataset.route;}});el.querySelector('[data-md-back]')?.addEventListener('click',()=>{UIState.set('response-tracking',{md:'list'});render(el)});
el.querySelector('[data-open-task]')?.addEventListener('click',e=>{State.patch({selectedId:e.currentTarget.dataset.openTask});location.hash='#/orchestrator'});
el.querySelector('[data-ack]')?.addEventListener('click',async e=>{const id=e.currentTarget.dataset.ack;const item=matrixRows(State.get()).find(x=>x.__id===id);if(!item)return;if(!await confirmAction({title:'Acknowledge task',body:`<p>${esc(item.title)}</p><p>Executor: ${esc(item.assignedTo)}</p>`,confirmText:'Confirm receipt',cancelText:'Cancel'}))return;await executeOwnedAction('acknowledgment','acknowledge',()=>{const r=acknowledgeTask(State.get(),id,State.get().profile.email,{surface:'response-tracking'});if(r)State.patch(r.patch,{action:'response:acknowledge',module:'response-tracking',ref:item.referenceId});},{ref:item.referenceId});toast('Task acknowledged','success');render(el)});
el.querySelector('[data-forward]')?.addEventListener('click',async e=>{const id=e.currentTarget.dataset.forward;const item=matrixRows(State.get()).find(x=>x.__id===id);if(!item)return;if(!await confirmAction({title:'Forward matrix trace to registry',body:`<p>Forward ${esc(item.title)} into governed registry routing?</p>`,confirmText:'Forward',cancelText:'Cancel'}))return;try{await invoke('DYNAMIC_ACTIONS',{operation:'route',ref:item.referenceId,title:item.title});toast('Forwarded to registry workflow','success')}catch{toast('Recorded locally; synchronization queued','error')}State.patch({selectedId:item.referenceId},{action:'response:forward-registry',module:'response-tracking',ref:item.referenceId});location.hash='#/registry'});}

