import { WelcomeExperience } from '../core/welcome-experience.js';
import { hydrateGovernance, executeOwnedAction } from '../core/governed-actions.js';
import { DataReconciler } from '../core/data-reconciler.js';
import { State } from '../core/state.js';
import { normalize } from '../core/domain.js';
import { head, toast, esc, confirmAction } from '../core/ui.js';
import { EndpointKeys, DefaultEndpointSettings } from '../config/endpoints.config.js';
import { AppConfig } from '../config/app.config.js';
import { resetWelcomeExperience } from '../shared/welcome-runtime.js';
import { getCurrentUser, hasPermission } from '../core/current-user.js';
import { Permissions } from '../config/rbac.config.js';
export async function mount(el){hydrateGovernance();const s=State.get(), endpoints=s.settings.endpoints||{};const active=EndpointKeys.filter(k=>endpoints[k]).length;const currentUser=getCurrentUser(s), canChangePersona=hasPermission(currentUser, Permissions.ROLE_ASSIGN);el.innerHTML=`<div class="workspace">${head('Settings','Profile, theme, density, limits, import and endpoint configuration.')}<div class="panel"><b>${EndpointKeys.length}</b> total endpoints · <b>${active}</b> configured</div><form class="panel grid"><label>Name<input name="name" value="${esc(s.profile.name)}"></label><label>Email<input name="email" type="email" value="${esc(s.profile.email)}"></label><label>Persona${canChangePersona?`<select name="persona">${['admin','executive','registry','general'].map(x=>`<option>${x}</option>`).join('')}</select>`:`<input value="${esc(s.profile.persona)}" disabled><input type="hidden" name="persona" value="${esc(s.profile.persona)}"><small>Managed by User Admin</small>`}</label><label>Theme<select name="theme">${AppConfig.themes.map(x=>`<option>${x}</option>`).join('')}</select></label><label>Density<select name="density">${AppConfig.densities.map(x=>`<option>${x}</option>`).join('')}</select></label><label>MAX_BULK_ASSIGN<input name="max" type="number" min="1" value="${esc(s.settings.maxBulkAssign)}"></label>${EndpointKeys.map(k=>`<label class="wide">${k}<input name="${k}" value="${esc(endpoints[k]||'')}" placeholder="https://"></label>`).join('')}<div class="wide"><button class="btn">Preview & Save</button> <button type="button" class="btn ghost" data-import>Import Activities</button><button type="button" class="btn ghost" data-copy-endpoints>Copy Endpoint JSON</button><button type="button" class="btn ghost" data-restore-endpoints>Restore Previous Platform URLs</button><button type="button" class="btn ghost" data-reset-endpoints>Reset All Endpoints</button><button type="button" class="btn ghost" data-replay-welcome>Replay Welcome</button><button type="button" class="btn danger" data-clear-local>Clear Local Data</button><input hidden type="file" data-file accept="application/json"></div></form><section class="panel"><h2>Welcome Experience</h2><p class="meta">Reset the R11.6 boot, login, OTP and identity-verification welcome sequence for validation or training.</p><button class="btn" data-reset-welcome>Reset Welcome Experience</button></section></div>`;const f=el.querySelector('form'); f.addEventListener('click',e=>{ if(e.target?.matches?.('[data-replay-welcome]')) resetWelcomeExperience({launch:true}); });const field=n=>f.elements?.[n]||f.querySelector?.(`[name="${n}"]`)||null;['persona','theme','density'].forEach(n=>{const x=field(n); if(x) x.value=n==='persona'?s.profile.persona:n==='theme'?s.settings.theme:s.settings.density});f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)), max=Number(d.max);if(!Number.isInteger(max)||max<1)return toast('Bulk limit must be a positive integer','error');const configured=Object.fromEntries(EndpointKeys.map(k=>[k,String(d[k]||'').trim()]));const oldEndpoints=State.get().settings.endpoints||{};const changed=EndpointKeys.filter(k=>configured[k]!==oldEndpoints[k]);const nextPersona=canChangePersona?d.persona:State.get().profile.persona;const preview={profile:{name:d.name.trim(),email:d.email.trim(),persona:nextPersona},settings:{theme:d.theme,density:d.density,maxBulkAssign:max},endpointChanges:changed.map(k=>({key:k,from:oldEndpoints[k]?'configured':'blank',to:configured[k]?'configured':'blank'}))};if(!await confirmAction({title:'Confirm settings update',body:`<p>Review settings before applying. Endpoint changes: <b>${changed.length}</b>.</p>${actionPreview(preview)}`,confirmText:'Save settings',cancelText:'Cancel'}))return;State.patch({profile:{...State.get().profile,name:d.name.trim(),email:d.email.trim(),persona:nextPersona},settings:{...State.get().settings,theme:d.theme,density:d.density,maxBulkAssign:max,endpoints:configured}},{action:'settings:save',module:'settings',event:'audit:settings-save'});document.documentElement.dataset.theme=d.theme;document.documentElement.dataset.density=d.density;toast('Settings saved','success')};const fi=el.querySelector('[data-file]');el.querySelector('[data-import]').onclick=()=>fi.click();fi.onchange=async()=>{if(!fi.files?.[0])return;try{const d=JSON.parse(await fi.files[0].text()),rows=Array.isArray(d)?d:(d.activities||d.value||[]);if(!Array.isArray(rows))throw new Error('Activities array not found');await executeOwnedAction('settings','import-state',()=>DataReconciler.apply({activities:rows.map(normalize)},{module:'settings'}),{ref:rows.length+' activities'});toast('Imported '+rows.length+' activities','success')}catch(e){toast('Import failed: '+e.message,'error')}finally{fi.value=''}};el.querySelector('[data-copy-endpoints]').onclick=async()=>{const configured=Object.fromEntries(EndpointKeys.map(k=>[k,field(k)?.value||'']));const text=JSON.stringify(configured,null,2);try{await navigator.clipboard?.writeText(text);toast('Endpoint JSON copied to clipboard','success')}catch{toast(text,'info')}};el.querySelector('[data-restore-endpoints]').onclick=async()=>{if(!await confirmAction({title:'Restore endpoint URLs',body:'Restore all endpoint fields to the configured previous-platform URL set? Click Save afterwards to persist.',confirmText:'Restore',cancelText:'Cancel'}))return;EndpointKeys.forEach(k=>{const x=field(k); if(x) x.value=DefaultEndpointSettings[k]||''});toast('Endpoint URLs restored — click Save to apply','success')};el.querySelector('[data-reset-endpoints]').onclick=async()=>{if(!await confirmAction({title:'Clear endpoint fields',body:'Clear all endpoint fields? Live backend calls will be unavailable after Save until URLs are restored.',confirmText:'Clear fields',cancelText:'Cancel'}))return;EndpointKeys.forEach(k=>{const x=field(k); if(x) x.value=''});toast('Endpoint fields cleared — click Save to apply','success')};el.querySelector('[data-clear-local]').onclick=async()=>{if(!await confirmAction({title:'Clear local runtime data',body:'This clears local persisted state, profile/session settings, cached lists, pending queue and audit copy in this browser. Backend records are not deleted.',confirmText:'Clear local data',cancelText:'Cancel'}))return;State.reset();toast('Local data cleared','success');setTimeout(()=>location.reload(),250)}}

