import { hydrateGovernance } from '../core/governed-actions.js';
import { State } from '../core/state.js';
import { head, kpis, esc, toast, confirmAction,fmtDate, actionPreview} from '../core/ui.js';
import { status } from '../core/domain.js';
import { invoke } from '../core/api.js';
import { UIState } from '../core/ui-state.js';
import { normalizeReportRows, filterByDateRange, reportSummary, groupCount, downloadText } from '../core/report-export-service.js';
import { priorityLabel } from '../config/priority.config.js';
import { requestSync } from '../core/data-loader.js';
const templates=['M1','M2','M3','M4','M5','M6','M7','M8','M9','M10'];
let selected=new Set(['M1','M7','M9']), start='', end='', recipients=[];
function syncLocal(){const u=UIState.get('statistics',{templates:[...selected],start,end,recipients});selected=new Set(u.templates);start=u.start;end=u.end;recipients=[...u.recipients];}
const val=x=>String(x||'').toLowerCase();
const date=x=>fmtDate(x?.created||x?.start||'');
const pct=(n,d)=>d?Math.round(n/d*100)+'%':'N/A';
function rows(s){return filterByDateRange(normalizeReportRows(s),start,end);}
const group=(rows,key)=>groupCount(rows,key);
function barBlock(title,items){const max=Math.max(1,...items.map(x=>x[1]));return `<section class="report-template"><h2>${esc(title)}</h2>${items.slice(0,12).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><i style="--value:${v/max*100}%"></i><b>${v}</b></div>`).join('')||'<p>No data.</p>'}</section>`;}
function table(rows){return `<div class="tablewrap"><table><thead><tr><th>#</th><th>Title</th><th>Kind</th><th>Category</th><th>Priority</th><th>Status</th><th>Assigned To</th><th>Date</th><th>Link</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.title)}</td><td>${esc(r.kind)}</td><td>${esc(r.category)}</td><td>${esc(r.priority||'—')}</td><td>${esc(r.taskStatus||r.activityStatus||'—')}</td><td>${esc(r.assignedTo||'—')}</td><td>${esc(date(r))}</td><td>${r.attachmentLink?`<a href="${esc(r.attachmentLink)}" target="_blank" rel="noreferrer">View</a>`:'—'}</td></tr>`).join('')||'<tr><td colspan="9">No records.</td></tr>'}</tbody></table></div>`;}
function buildReport(id,data,s){const sum=reportSummary(data),total=data.length,completed=sum.completed,assigned=data.filter(r=>r.assignedTo).length;const cats=group(data,'category'),pri=groupCount(data,r=>priorityLabel(r.priority)),ass=group(data,'assignedTo'),stat=group(data.map(r=>({...r,stat:r.taskStatus||r.activityStatus||'Blank'})),'stat');
if(id==='M1')return `<section class="report-template"><h2>Report 38 — Digital Activity Report</h2>${kpis([['Total Records',total],['Completed/Assigned',completed],['Assigned Coverage',pct(assigned,total)],['Period',`${start||'All'} to ${end||'Now'}`]])}${table(data)}</section>`;
if(id==='M2')return `<section class="report-template"><h2>Management Report V1</h2><p>Comprehensive overview of activities, tasks and performance generated by ${esc(s.profile.name||s.profile.email)}.</p>${kpis([['Unique Categories',cats.length],['Average Assignment Time','Current-state derived'],['Rows',total],['Recipients',recipients.length]])}</section>`;
if(id==='M3')return barBlock('Status Donut Equivalent',stat);
if(id==='M4')return barBlock('Priority Breakdown',pri);
if(id==='M5')return barBlock('Category Breakdown',cats);
if(id==='M6')return barBlock('Assigned To Breakdown',ass);
if(id==='M7')return `<section class="report-template"><h2>24_2 — Comprehensive Overview</h2>${kpis([['Reference ID','REP-'+new Date().toISOString().replace(/[-:T.Z]/g,'').slice(0,14)],['Total',total],['Assigned',assigned],['Created',new Date().toLocaleString()]])}${table(data.slice(0,80))}</section>`;
if(id==='M8')return `<section class="report-template"><h2>Report 37 — Performance Summary</h2>${barBlock('Performance by Status',stat)}${barBlock('Performance by Priority',pri)}</section>`;
if(id==='M9')return `<section class="report-template"><h2>SharePoint Report Gallery</h2><div class="list-col">${data.slice(0,60).map(r=>`<article class="list-item"><h4>${esc(r.title)}</h4><div class="meta">${esc(r.kind)} · ${esc(r.category)} · ${esc(date(r))}</div></article>`).join('')||'<p>No records.</p>'}</div></section>`;
return `<section class="report-template"><h2>Performance Charts</h2>${barBlock('Category',cats)}${barBlock('Assignee',ass)}</section>`;}
function htmlDoc(s,data){return `<!doctype html><html><head><meta charset="utf-8"><title>NITDA Stats Report</title></head><body><h1>NITDA Stats Report</h1>${[...selected].map(t=>buildReport(t,data,s)).join('')}</body></html>`;}
export async function mount(el){hydrateGovernance();render(el);}
function render(el){syncLocal();const s=State.get(),data=rows(s),treated=s.activities.filter(a=>['Treated','Processed'].includes(status(a))).length,assigned=s.activities.filter(a=>a.assignedTo).length,cats=group(data,'category');el.innerHTML=`<div class="workspace">${head('Statistics','Distribution, throughput, performance reports, recipient-controlled email dispatch and data-completeness analysis.')}
${kpis([['Treatment rate',pct(treated,s.activities.length)],['Assignment coverage',pct(assigned,s.activities.length)],['Rows in range',data.length],['Users',s.users.length]])}
<section class="panel"><div class="toolbar"><label>From <input type="date" data-date="start" value="${esc(start)}"></label><label>To <input type="date" data-date="end" value="${esc(end)}"></label><button class="btn" data-generate>Generate Report</button><button class="btn ghost" data-html>Download HTML</button><button class="btn ghost" data-sp>Get SharepointReport</button></div><div class="chips">${templates.map(t=>`<button class="chip ${selected.has(t)?'active':''}" data-template="${t}" aria-pressed="${selected.has(t)}">${selected.has(t)?'✓ ':''}${t}</button>`).join('')}<button class="chip" data-all>All</button><button class="chip" data-none>None</button></div><div class="recip-input-row"><span class="meta">Recipients</span>${recipients.map(r=>`<span class="recip-chip">${esc(r)} <span class="x" data-remove-recipient="${esc(r)}">×</span></span>`).join('')}<input data-recipient placeholder="Type email and press Enter"></div><div class="form-row"><button class="btn" data-send-att>Send Report w/ Attachment</button><button class="btn" data-send-perf>Send Performance w/ Attachment</button></div></section>
<div class="dashboard-grid"><section class="panel">${barBlock('Category distribution',cats)}</section><section class="panel">${barBlock('Dispatch channels',group(s.dispatches,'channel'))}</section><section class="panel">${barBlock('Data completeness',[['Reference IDs',s.activities.filter(a=>a.referenceId).length],['Document links',s.activities.filter(a=>a.attachmentLink).length],['Categories',s.activities.filter(a=>a.category).length],['Assignees',assigned]])}</section></div><section class="panel" id="stats-report-body">${[...selected].map(t=>buildReport(t,data,s)).join('')||'<div class="empty">No report view selected.</div>'}</section></div>`;
el.querySelectorAll('[data-date]').forEach(i=>i.onchange=()=>{UIState.set('statistics',i.dataset.date==='start'?{start:i.value}:{end:i.value});render(el)});el.querySelectorAll('[data-template]').forEach(b=>b.onclick=()=>{selected.has(b.dataset.template)?selected.delete(b.dataset.template):selected.add(b.dataset.template);UIState.set('statistics',{templates:[...selected]});render(el)});el.querySelector('[data-all]').onclick=()=>{UIState.set('statistics',{templates:[...templates]});render(el)};el.querySelector('[data-none]').onclick=()=>{UIState.set('statistics',{templates:[]});render(el)};el.querySelector('[data-recipient]').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const v=e.target.value.trim();if(v&&/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)&&!recipients.includes(v))UIState.set('statistics',{recipients:[...recipients,v]});render(el)}};el.querySelectorAll('[data-remove-recipient]').forEach(x=>x.onclick=()=>{UIState.set('statistics',{recipients:recipients.filter(r=>r!==x.dataset.removeRecipient)});render(el)});el.querySelector('[data-generate]').onclick=()=>{if(!data||!data.length){toast('No report rows for the selected range/templates','info');return;}download(htmlDoc(s,data),'nitda-stats-report.html','text/html');toast('Report generated and downloaded','success');};el.querySelector('[data-html]').onclick=()=>download(htmlDoc(s,data),'nitda-stats-report.html','text/html');el.querySelector('[data-sp]').onclick=async()=>{if(!await confirmAction({title:'Get SharepointReport',body:`<p>Fetch current report rows from governed backend?</p>${actionPreview({start,end,templates:[...selected]})}`}))return;try{await requestSync({source:'statistics',mode:'endpoint',endpoint:'FETCH_ALL',payload:{action:'lookupTasksReports',start,end}});toast('SharePoint report request sent','success')}catch{toast('Endpoint unavailable; current state report remains visible','error')}};el.querySelector('[data-send-att]').onclick=()=>sendReport(s,data,'Stats Report with Attachment');el.querySelector('[data-send-perf]').onclick=()=>sendReport(s,data,'Performance Report with Attachment');}
const download=(content,name,type)=>downloadText(name,content,type);
async function sendReport(s,data,subject){syncLocal();if(!recipients.length)return toast('Add at least one recipient','error');const payload={subject,to:recipients,templates:[...selected],start,end,rowCount:data.length,html:htmlDoc(s,data)};if(!await confirmAction({title:'Confirm report email',body:`<p>${esc(subject)}</p>${actionPreview({...payload,html:'[redacted-html]'})}`,confirmText:'Send report',cancelText:'Cancel'}))return;try{await invoke('EMAIL',payload);toast('Report email sent','success')}catch{toast('Endpoint unavailable; report dispatch queued locally','error')}}

