*{box-sizing:border-box}html,body{margin:0;width:100vw;height:100vh;height:100dvh;overflow:hidden;background:var(--bg);color:var(--fg);font-family:var(--body)}
button,input,select,textarea{font:inherit}.skip{position:fixed;left:-9999px}.skip:focus{left:6px;top:6px;z-index:999;background:var(--s);padding:8px;border-radius:var(--rc)}.boot,.fatal{padding:30px}.fatal{color:var(--danger)}
.ministry{height:var(--ministry);background:var(--dark);color:var(--mint);display:flex;align-items:center;justify-content:flex-end;padding:0 16px;font:700 8px var(--sans);letter-spacing:.11em;overflow:hidden}
.top{height:var(--header);background:var(--s);border-bottom:1px solid var(--bd);display:flex;align-items:center;gap:9px;padding:6px 12px;position:relative;z-index:30;min-width:0}.logo{width:184px;height:42px;flex:0 0 auto}.context{border-left:1px solid var(--bd);padding-left:10px;display:grid;line-height:1.1;min-width:145px}.context small{font:700 8px var(--sans);letter-spacing:.1em;color:var(--mut)}.context b{font:700 12px var(--display);color:var(--strong);margin-top:3px}.grow{flex:1;min-width:0}.header-search{height:34px;width:clamp(180px,24vw,350px);display:flex;align-items:center;gap:6px;background:var(--sunken);border:1px solid var(--bd);border-radius:var(--rc);padding:0 8px;min-width:0}.header-search input{border:0;background:transparent;box-shadow:none;min-height:30px;padding:3px;min-width:0}.btn,.iconbtn{min-height:34px;border:1px solid var(--p);background:var(--p);color:#fff;border-radius:var(--rc);padding:0 12px;display:inline-flex;align-items:center;justify-content:center;gap:6px;text-decoration:none;cursor:pointer;font:700 11px var(--sans);white-space:nowrap}.btn.ghost,.iconbtn{background:var(--s);color:var(--p);border-color:var(--bd)}.iconbtn{width:36px;padding:0}.btn:hover{background:var(--a);border-color:var(--a)}:focus-visible{outline:0;box-shadow:var(--focus)}
.shell{height:calc(100vh - var(--ministry) - var(--header));height:calc(100dvh - var(--ministry) - var(--header));width:100vw;display:grid;grid-template-columns:var(--nav-expanded) minmax(0,1fr);overflow:hidden;transition:grid-template-columns .16s ease}.shell.collapsed{grid-template-columns:var(--nav-collapsed) minmax(0,1fr)}
