.dg-layout{display:grid;grid-template-columns:minmax(260px,1fr) minmax(340px,1.5fr) minmax(260px,.9fr);gap:12px;align-items:start}.dashboard-metrics{display:flex;gap:8px;flex-wrap:wrap;margin:8px 0 14px}.tag{display:inline-flex;align-items:center;gap:4px;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:800}.tag.overdue{background:var(--danger-soft);color:var(--danger)}.tag.awaiting{background:var(--warn-soft);color:var(--warn)}.tag.ok{background:var(--ok-soft);color:var(--ok)}.tag.neutral{background:var(--neutral-soft);color:var(--mut)}.doc-list-title{font-weight:800;display:block;margin-bottom:4px}.matrix-card{background:var(--sunken);border:1px solid var(--bd);border-radius:10px;padding:10px;margin:8px 0}.matrix-meta{font-size:12px;color:var(--mut);margin:3px 0}.ai-preview{background:color-mix(in srgb,var(--gold) 9%,transparent);border:1px solid color-mix(in srgb,var(--gold) 40%,transparent);border-radius:12px;padding:12px;margin:12px 0}.ea-only,.dg-only{display:block}.role-DGCEO .ea-only,.role-Officer .dg-only,.role-Officer .ea-only{display:none!important}.role-EA .dg-only{display:none!important}@media(max-width:1000px){.dg-layout{grid-template-columns:1fr}.panel-actions{display:block}}

