  --dgo-bp-sm: 600px;
  --dgo-bp-md: 905px;
  --dgo-bp-lg: 1240px;
  --dgo-bp-xl: 1440px;
  --dgo-bp-2xl: 1920px;

  /* ---------- Container widths ---------- */
