tests/cascade-downstream-contract.mjs.content:
// Cascade must recompute downstream fields when an upstream dropdown changes:
// category change -> subcategory/dsu/assignee recompute; DSU change -> assignee recomputes;
// manual edits are preserved.
import assert from 'node:assert/strict';
globalThis.localStorage={store:{},getItem(k){return this.store[k]||null},setItem(k,v){this.store[k]=v},removeItem(k){delete this.store[k]}};
const { AssignmentCascade } = await import('../core/assignment-cascade.js');
const state={categories:[
 {category:'Correspondence',categoryCode:'CR',subcategory:'Inbound',subcategoryCode:'IN',dsuKey:'DSU-ICT',assignedTo:'ict.head@x'},
 {category:'Procurement',categoryCode:'PR',subcategory:'Tender',subcategoryCode:'TN',dsuKey:'DSU-PROC',assignedTo:'proc.head@x'}],
 departments:[{dsuKey:'DSU-ICT',title:'ICT',headEmail:'ict.head@x'},{dsuKey:'DSU-REG',title:'Registry',headEmail:'reg.head@x'},{dsuKey:'DSU-PROC',title:'Procurement',headEmail:'proc.head@x'}],users:[]};
const a={id:'x1',title:'T',referenceId:'R1'};
let d=AssignmentCascade.cascade({activity:a,draft:{},state,changed:'initial'});
d=AssignmentCascade.cascade({activity:a,draft:{...d,category:'Procurement'},state,changed:'category'});
assert.equal(d.dsu,'DSU-PROC','category change must recompute DSU'); assert.equal(d.assignedTo,'proc.head@x','category change must recompute assignee');
d=AssignmentCascade.cascade({activity:a,draft:{...d,dsu:'DSU-REG'},state,changed:'dsu'});
assert.equal(d.dsu,'DSU-REG','DSU choice must be preserved'); assert.equal(d.assignedTo,'reg.head@x','DSU change must recompute assignee');
d=AssignmentCascade.cascade({activity:a,draft:{...d,assignedTo:'manual@x'},state,changed:'manual'});
assert.equal(d.assignedTo,'manual@x','manual edit must be preserved');
console.log('cascade-downstream-contract passed');

tests/cascade-summary-contract.mjs.content:
// Cascade must derive the Assignment-Summary fields the way the reference Power Automate cascade does:
//  - Assignee Title from the primary department's DSU_HeadTitle
//  - CC recipients from INFORMDSU1/2/3 resolved to each department head's (personal) email
//  - Support DSU / co-assignee from Default Supporting Department/Unit
// Uses the reference's exact SharePoint/Power-Automate column names.
import assert from 'node:assert/strict';
globalThis.localStorage={store:{},getItem(k){return this.store[k]||null},setItem(k,v){this.store[k]=v},removeItem(k){delete this.store[k]}};
const { AssignmentCascade } = await import('../core/assignment-cascade.js');
const state={
  categories:[{
    Category:'Executive Correspondence', 'Category Code':'EXC', Subcategory:'DG Attention', 'SubCategory Code':'DG',
    'Default Primary Responsible':'DSU-ODG', 'Default Supporting Department/Unit':'DSU-REG',
    INFORMDSU1:'DSU-LEG', INFORMDSU2:'DSU-ICT', Priority:'high'
  }],
  departments:[
    {DSU_KEY:'DSU-ODG', Title:'Office of the DG', DSU_HeadEmail:'dg.head@nitda.gov.ng', DSU_HeadPersonalEmail:'dg.personal@nitda.gov.ng', DSU_HeadTitle:'Director-General'},
    {DSU_KEY:'DSU-REG', Title:'Registry', DSU_HeadEmail:'reg.head@nitda.gov.ng', DSU_HeadTitle:'Head, Registry'},
    {DSU_KEY:'DSU-LEG', Title:'Legal', DSU_HeadEmail:'leg.head@nitda.gov.ng', DSU_HeadPersonalEmail:'leg.personal@nitda.gov.ng', DSU_HeadTitle:'Director, Legal'},
    {DSU_KEY:'DSU-ICT', Title:'ICT', DSU_HeadEmail:'ict.head@nitda.gov.ng', DSU_HeadPersonalEmail:'ict.personal@nitda.gov.ng', DSU_HeadTitle:'Director, ICT'}
  ], users:[]
};
const a={id:'e1', title:'Executive memo', referenceId:'R-EXC-1'};
let d=AssignmentCascade.cascade({activity:a, draft:{}, state, changed:'initial'});
d=AssignmentCascade.cascade({activity:a, draft:{...d, category:'Executive Correspondence'}, state, changed:'category'});

assert.equal(d.dsu,'DSU-ODG','primary DSU from Default Primary Responsible');
assert.equal(d.assignedTo,'dg.head@nitda.gov.ng','assignee from primary department head email');
assert.equal(d.assigneeTitle,'Director-General','assignee title from DSU_HeadTitle');
assert.equal(d.supportDsu,'DSU-REG','support DSU from Default Supporting Department/Unit');
assert.equal(d.supportingAssignee,'reg.head@nitda.gov.ng','co-assignee from support department head');
// CC = INFORMDSU1/2/3 resolved to each dept head's personal email (falls back to head email).
const cc=d.copy.split(/[;,]+/).map(x=>x.trim()).filter(Boolean);
assert.deepEqual(cc,['leg.personal@nitda.gov.ng','ict.personal@nitda.gov.ng'],'CC from INFORMDSU personal emails');

// Changing the primary DSU must re-derive both assignee AND assignee title.
d=AssignmentCascade.cascade({activity:a, draft:{...d, dsu:'DSU-ICT'}, state, changed:'dsu'});
assert.equal(d.assignedTo,'ict.head@nitda.gov.ng','DSU change re-derives assignee');
assert.equal(d.assigneeTitle,'Director, ICT','DSU change re-derives assignee title');

console.log('cascade-summary-contract passed');

tests/data-load-graceful-contract.mjs.content:
// Initial live-data failure must not render a blocking red error toast over the workspace.
import assert from 'node:assert/strict';
import fs from 'node:fs';
const boot=fs.readFileSync('core/boot.js','utf8');
assert.doesNotMatch(boot,/Live data could not be loaded/,'boot must not show noisy red live-data error toast on initial load');
assert.match(boot,/data-load-deferred/,'boot must record deferred/offline live-data state for diagnostics');
assert.match(boot,/lastWarnings/,'boot must preserve diagnostics warning detail without blocking UI');
console.log('data-load-graceful-contract passed');

tests/dynamic-text-overflow-contract.mjs.content:
// Corrected audit P3: dynamic text must not create horizontal overflow or unbounded line growth.
import assert from 'node:assert/strict';
import fs from 'node:fs';
const css=fs.readFileSync('styles/app.css','utf8');
assert.match(css,/\.dgo-table th,[\s\S]*?\.alert\{[^}]*overflow-wrap:anywhere/s,'dynamic table/card/dialog text must wrap safely');
assert.match(css,/\.dgo-record-row__main strong,[\s\S]*?\.cc-detail-title\{[^}]*text-overflow:ellipsis/s,'dynamic titles must truncate rather than escape their container');
assert.match(css,/\.dgo-clamp-2,[\s\S]*?\.source-guidance-card p\{[^}]*-webkit-line-clamp:2/s,'two-line clamp utility must exist for dynamic summaries');
assert.match(css,/\.dgo-clamp-3,[\s\S]*?\.module-rule-copy\{[^}]*-webkit-line-clamp:3/s,'three-line clamp utility must exist for operational narrative text');
console.log('dynamic-text-overflow-contract passed');

tests/import-smoke-generated.mjs.content:
import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const roots=['config','core','shared','modules'];
const files=roots.flatMap(d=>fs.readdirSync(d).filter(f=>f.endsWith('.js')).map(f=>path.join(d,f))).sort();
const failures=[];
for(const f of files){try{await import(pathToFileURL(path.resolve(f)).href+'?smoke='+Date.now());}catch(e){failures.push({file:f,error:e.message});}}
console.log(JSON.stringify({files:files.length,failures:failures.length,details:failures},null,2));
if(failures.length) process.exit(1);

tests/layout-footer-contract.mjs.content:
// Shell layout invariants:
//  - footer always present (has a :root --footer default, shell grid bounds its row,
//    and the footer is NOT display:none'd on short viewports);
//  - the main content area is the SINGLE scroll container — no nested/independent section
//    scrolling (master-detail panes and the record body must flow, not scroll on their own);
//  - the top-bar workspace identity is compact (small, non-wrapping);
//  - the redundant in-page intro header is suppressed platform-wide.
import assert from 'node:assert/strict'; import fs from 'node:fs';
const css=fs.readFileSync('styles/app.css','utf8');
const ui=fs.readFileSync('core/ui.js','utf8');
const corr=fs.readFileSync('modules/correspondence.js','utf8');

// Footer present & pinned.
assert.match(css,/:root\{[^}]*--footer:\d+px/,'--footer must have a :root default');
assert.match(css,/\.dgo-shell-grid\{[^}]*grid-template-rows:minmax\(0,1fr\)/,'shell grid must bound its row so the footer stays in view');
assert.doesNotMatch(css,/max-height:640px\)\{[^}]*\.dgo-footer\{display:none\}/,'footer must not be hidden on short viewports');

// Single scroll container: main scrolls; panes and record body do not scroll independently.
assert.match(css,/\.dgo-main\{[^}]*overflow:hidden !important/,'main must be bounded and must not become the page scroll container');
assert.match(css,/\.split>\*[^}]*overflow:auto !important/s,'master-detail panes must scroll independently');
assert.match(css,/\.dg-layout>\.panel[^}]*overflow:auto !important/s,'DG layout panes must scroll independently');
assert.match(css,/\.record-body\{[^}]*overflow:auto !important/,'record body must scroll internally when long');

// Compact top-bar identity (small + non-wrapping).
assert.match(css,/\.dgo-route-title b\{font-size:1[0-3]px;[^}]*white-space:nowrap/,'workspace name must be small and non-wrapping');
assert.match(css,/\.dgo-route-title small\{font-size:[0-9]px/,'ACTIVE WORKSPACE eyebrow must be reduced');

// Condensed correspondence controls + suppressed intro header.
assert.match(css,/\.cc-controlbar\{/,'condensed control strip styles must exist');
assert.match(css,/\.cc-stat\{[^}]*height:2[0-9]px/,'metric pills must be compact (<= half header height)');
// The VISIBLE intro block (eyebrow + big title + subtitle) must be suppressed platform-wide; a single
// visually-hidden <h1> is retained so every workspace still exposes one programmatic heading (a11y).
assert.match(ui,/export const head = [^\n]*dgo-visually-hidden/,'head() must emit only a visually-hidden heading (no visible intro block)');
assert.doesNotMatch(ui,/export const head = [^\n]*(dgo-overline|pagehead|dgo-module-view__head)/,'head() must not render the visible eyebrow/pagehead intro block');
assert.doesNotMatch(corr,/class="dashboard-metrics"/,'duplicate status band must be removed from the tracker view');
assert.doesNotMatch(corr,/\$\{head\(/,'correspondence must not render the removed intro header');

console.log('layout-footer-contract passed');

