tests/ui-polish-contract.mjs.content:
// Interface polish: toolbar must wrap (search never collapses) and tables must not be
// forced wider than a typical full-width workspace panel.
import assert from 'node:assert/strict'; import fs from 'node:fs';
const css=fs.readFileSync('styles/app.css','utf8');
const tb=css.match(/\.toolbar\{[^}]*\}/); assert.ok(tb);
assert.match(tb[0],/flex-wrap:wrap/,'.toolbar must wrap');
const tbi=css.match(/\.toolbar input\{[^}]*\}/); assert.ok(tbi);
assert.match(tbi[0],/min-width:2\d\dpx|min-width:1[5-9]\dpx/,'.toolbar input must keep a usable min-width');
assert.doesNotMatch(tbi[0],/min-width:0(?![.\d])/,'.toolbar input must not collapse to 0');
const tw=css.match(/\.tablewrap table\{[^}]*\}/); assert.ok(tw);
const mw=+(tw[0].match(/min-width:(\d+)px/)||[])[1];
assert.ok(mw && mw<=600,`table min-width must be <=600px so full-width tables do not clip (got ${mw})`);
assert.match(css,/\.tablewrap[^{]*::-webkit-scrollbar/,'tables must have a visible scrollbar affordance');
console.log('ui-polish-contract passed');

tests/user-enrollment-rbac-contract.mjs.content:
// User enrollment provisioning contract: roles/status in users[] must be the runtime authority.
import assert from 'node:assert/strict';
import fs from 'node:fs';
const current=fs.readFileSync('core/current-user.js','utf8');
const router=fs.readFileSync('core/router.js','utf8');
const state=fs.readFileSync('core/state.js','utf8');
const ua=fs.readFileSync('modules/user-admin.js','utf8');
const rbac=fs.readFileSync('config/rbac.config.js','utf8');
const settings=fs.readFileSync('modules/settings.js','utf8');
const ownership=fs.readFileSync('config/action-ownership.config.js','utf8');
const authority=fs.readFileSync('core/action-authority.js','utf8');
assert.match(current,/export function getCurrentUser/,'current-user resolver must exist');
assert.match(current,/users\.find\(u=>normalizeEmail\(u\.email\)===email\)/,'current user must bind profile.email to users[]');
assert.match(current,/status:'unregistered'/,'unregistered profiles must be represented explicitly');
assert.match(router,/canCurrentUserAccess\(p\)/,'router must use enrolled current-user access, not only profile persona');
assert.doesNotMatch(router,/canAccess\(State\.get\(\)\.profile\.persona/,'router must not gate solely on profile persona');
assert.match(state,/bootstrapUsers=\[/,'state must seed a bootstrap administrator');
assert.match(ua,/name="persona"/,'user-admin must provision persona on user records');
assert.match(ua,/assign-role/,'user-admin must explicitly execute assign-role when role/persona changes');
assert.match(ua,/persistUserMutation/,'user-admin must attempt central persistence for user mutations');
assert.match(ua,/PendingQueue\.enqueue/,'user-admin must queue offline user-admin writes');
assert.match(ownership,/'assign-role': \{ owner:'user-admin'/,'assign-role must be an owned auditable action');
assert.match(authority,/ensureCurrentUserActive/,'actions must be blocked for disabled/unregistered users');
assert.match(rbac,/RoleRouteAccess/,'RBAC must contain role route access mapping');
assert.match(settings,/canChangePersona=hasPermission\(currentUser, Permissions\.ROLE_ASSIGN\)/,'settings persona changes must be role-assignment governed');
console.log('user-enrollment-rbac-contract passed');

